// Playtest #26, F12's objectives box (0x00446ad0, docs/hud.md, The
// objectives box): on c1m1 F12 shows the mission's header, the primary
// objectives' title and each visible objective "In Progress" beside it, the
// secondary group's, and the closing line with F12's key name; the panel is
// as tall as the lines, each line with its score (0x00446930 adds a blank
// one). The four SRM emplacements destroyed, their line reads "Completed"
// (the completion refills the box, 0x0045e110).
TEST(mission_c1m1_objectives_box_text_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("mission_objbox_write"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::options() = mech3::Options{};
  struct Keys : platform::Input {
    std::vector<platform::KeyEvent> queue;
    uint32_t t = 0;
    void key(uint32_t dik, bool down) { queue.push_back({dik, down ? 0x80u : 0u, ++t, t}); }
    bool open(Device d) override { return d == kKeyboard; }
    void close(Device) override {}
    int32_t acquire(Device) override { return 0; }
    int32_t unacquire(Device) override { return 0; }
    int32_t keyboard_data(platform::KeyEvent* out, uint32_t* count) override {
      const uint32_t n = std::min<uint32_t>(*count, static_cast<uint32_t>(queue.size()));
      std::copy(queue.begin(), queue.begin() + n, out);
      queue.erase(queue.begin(), queue.begin() + n);
      *count = n;
      return 0;
    }
    int32_t mouse_state(platform::MouseState*) override { return kNotAcquired; }
    int32_t joystick_state(platform::JoyState*) override { return kNotAcquired; }
  } keys;
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  p.input = &keys;
  mech3::HudObjectivesReport before, after, closed;
  bool got = false, got2 = false, got3 = false;
  int killed = 0;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;  // c1m1
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    int frames = 0;
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core) return;
      ++frames;
      const uint32_t f12 = zin::key1_of(0x43) & 0xff;
      if (frames == 20) keys.key(f12, true);
      if (frames == 21) keys.key(f12, false);
      if (frames == 24) got = mech3::program_hud_objectives(&before);
      if (frames == 25)  // the four SRM emplacements: "Destroy Fixed Emplacements"
        for (mech3::tur::Turret* x : mech3::tur::turret_list())
          if (std::strncmp(static_cast<zcls::Node*>(engine.object_of(x->node))->name(), "tur_srm0", 8) == 0 &&
              static_cast<zcls::Node*>(engine.object_of(x->node))->name()[8] <= '4') {
            ++killed;
            x->kill();  // vt+0x70
          }
      if (frames == 30) got2 = mech3::program_hud_objectives(&after);
      if (frames == 31) keys.key(f12, true);
      if (frames == 32) keys.key(f12, false);
      if (frames == 34) got3 = mech3::program_hud_objectives(&closed);
    };
    CountingPump pump;
    pump.stop = [&] { return frames >= 35; };
    pump.limit = 100000;
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  auto dump = [](const char* what, const mech3::HudObjectivesReport& r) {
    std::printf("  %s: shown %d, panel %d px, %zu lines / %zu scores\n", what, r.shown, r.panel_height, r.lines.size(),
                r.scores.size());
    for (size_t i = 0; i < r.lines.size(); ++i)
      std::printf("    [%s]%s%s\n", r.lines[i].c_str(), i < r.scores.size() ? " | " : "",
                  i < r.scores.size() ? r.scores[i].c_str() : "");
  };
  dump("F12", before);
  dump("the emplacements destroyed", after);
  auto has = [](const std::vector<std::string>& v, const char* s) {
    for (const std::string& x : v)
      if (x.find(s) != std::string::npos) return true;
    return false;
  };
  auto count = [](const std::vector<std::string>& v, const char* s) {
    int n = 0;
    for (const std::string& x : v) n += x == s;
    return n;
  };
  EXPECT(got && got2 && got3 && killed == 4);
  EXPECT(before.shown && before.lines.size() >= 5);
  EXPECT(has(before.lines, "P R I M A R Y") || has(before.lines, "Primary"));
  EXPECT(has(before.lines, "To Close Objectives Display"));
  EXPECT(count(before.scores, "In Progress") >= 2 && count(before.scores, "Completed") == 0);
  EXPECT(before.panel_height == static_cast<int32_t>(before.lines.size()) * before.line_height);
  EXPECT(before.scores.size() == before.lines.size());
  EXPECT(count(after.scores, "Completed") == 1);
  EXPECT(!closed.shown);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

// c1 mission 1 won and lost through its objectives (docs/objectives.md,
// piece 4), from the menus as campaign_menus_to_c1m1 plays it, to the
// debriefing. Won: the comm centre's satdish destroyed (its health_below
// sets comcntr_down), reach_mfb set as aiv.zrd's reg_mfb region would (the
// regions are the AI's), Exit Mission. Lost: the player moved out of the
// mission's boundary (his own vlist sets outside_c1m1 from reg_outside_c1m1),
// or the player's mech destroyed. The four SRM emplacements are
// aiTurrets.zrd's turrets, found by the objectives (0x004d7330) and alive at
// the start; the won scenario kills them as well.
// c1m2's secondary objectives name its two mechs (destroy owens_01,
// strider_01). Each is shot by the player's hits through zWeapon's impact
// (chain_hit, the campaign chain's) until it dies; its objective is met once
// its death fall ends and its +0x08 clears (0x0045f3b0), though the wreck
// stays on zEntity's list (campaign.md section 14). Its salvage is its
// weapons (the kill credit's 0x00472f00).
// Every hooks field the ported code calls through (a function pointer or a
// std::function, tests/hook_fields.inc from tools/analysis/hookaudit.py) is
// set once the program has started and loaded a mission, unless the allow
// list says why it may stay null: a null hook is skipped silently, and the
// census cannot see it (zEffect's run hooks, campaign.md section 14).
struct HookField {
  const char* name;
  bool (*null)();
};
const std::vector<HookField>& hook_fields();  // test_hooks.cpp

TEST(program_hooks_set_after_a_mission_load_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("program_hooks"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  std::vector<std::string> nulls;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;
    l.index = 0, l.number = 1;  // c1m1
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    int core_frames = 0;
    engine.on_present = [&](int) {
      if (app.current() == &mech3::states().core && ++core_frames == 60)
        for (const HookField& h : hook_fields())
          if (h.null()) nulls.push_back(h.name);
    };
    CountingPump pump;
    pump.limit = 2400;
    pump.stop = [&] { return core_frames >= 60; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  std::printf("  hooks: %zu fields, %zu null in c1m1's Core\n", hook_fields().size(), nulls.size());
  if (std::getenv("MW3_HOOKS_LIST"))
    for (const std::string& n : nulls) std::printf("    null %s\n", n.c_str());
  // tests/hook_allow.txt: each null with its reason; an entry not null is stale.
  std::map<std::string, std::string> allow;
  if (std::FILE* f = std::fopen(MW3_SOURCE_DIR "/tests/hook_allow.txt", "r")) {
    char buf[512];
    while (std::fgets(buf, sizeof buf, f)) {
      std::string l = buf;
      if (l.empty() || l[0] == '#') continue;
      const size_t tab = l.find('\t');
      if (tab == std::string::npos) continue;
      allow[l.substr(0, tab)] = l.substr(tab + 1, l.find_last_not_of("\r\n") - tab);
    }
    std::fclose(f);
  }
  EXPECT(!allow.empty());
  static const char* const kWhy[] = {"counted: ", "fallback: ", "default: ", "multiplayer: ", "no effect: ",
                                     "never set: ", "deferred: ", "test: ", "data: "};
  int unexplained = 0, stale = 0;
  for (const std::string& n : nulls) {
    const auto it = allow.find(n);
    bool ok = it != allow.end() && it->second.size() > 14;
    if (ok) {
      ok = false;
      for (const char* w : kWhy) ok |= it->second.rfind(w, 0) == 0;
    }
    if (!ok) ++unexplained, std::printf("    null without a reason: %s\n", n.c_str());
  }
  for (const auto& [n, why] : allow)
    if (std::find(nulls.begin(), nulls.end(), n) == nulls.end()) ++stale, std::printf("    allowed but set: %s\n", n.c_str());
  EXPECT(unexplained == 0);
  EXPECT(stale == 0);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

// Multiplayer piece 8d in a running network game (c1mp1 over the hub, as
// the soak's debug start): the pilot killed; with respawn on (the game's
// +0x8c) it is made again 7.1 s on (the dead list's 0x0046dde0), alive and
// whole at one of the map's starts; with it off it stays dead and the view
// takes camera 4.
static void net_respawn_run(bool respawn, bool* died, bool* back, float* health, int32_t* camera) {
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("net_respawn_write"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  znet::Hub hub;
  znet::session() = znet::Session{};
  znet::initialise(hub.endpoint());
  EXPECT(znet::host_session(znet::SessionDesc{}, "Host"));
  *died = *back = false, *health = 0, *camera = -9;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::MultiplayerGame game(nullptr);
    game.x70 = 1 << 30;
    game.b8c = respawn ? 1 : 0;
    mech3::GameEngine::Launch l;
    l.index = 0, l.number = 1, l.type = 3, l.multi = &game;
    engine.set_launch(l);
    mech3::program_net_debug_lobby();
    app.post_intro_ = &mech3::states().load;
    int core_frames = 0, dead_frames = 0;
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core) return;
      ++core_frames;
      float h, at[3];
      const bool alive = mech3::program_pilot_alive(&h, at);
      if (core_frames == 30) *died = mech3::program_net_staged_kill();
      if (*died && !alive) ++dead_frames;
      if (*died && dead_frames > 0 && alive && !*back) *back = true, *health = h;
      *camera = mech3::program_view_camera_id();
    };
    CountingPump pump;
    pump.limit = 2600;
    pump.stop = [&] { return *back || core_frames > 1500; };  // about 8 ms a frame here: 7.1 s dead is ~900
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  znet::shutdown();
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::options() = mech3::Options{};
}
TEST(net_pilot_respawns_c1mp1_headless) {
  if (!have_game()) return;
  bool died, back;
  float health;
  int32_t camera;
  net_respawn_run(true, &died, &back, &health, &camera);
  std::printf("  respawn on: died %d, back %d, health %.3f\n", died, back, health);
  EXPECT(died && back && health > 0.99f);
  net_respawn_run(false, &died, &back, &health, &camera);
  std::printf("  respawn off: died %d, back %d, camera %d\n", died, back, camera);
  EXPECT(died && !back && camera == 4);
}

// The mobile bases' stations in a network game (0x00490950, after piece
// 11c): c1mp1 launched as a network game with ALLOW MOBILE BASES on; at each
// point of the mission's waynet a copy of the world's mfb_station01, named
// mfb_station_04 on (after the data's own labels, 01 and 02 here), in the
// world, standing on the point, shown, the point's label its name. Off, none.
TEST(net_mobile_base_stations_c1mp1_headless) {
  if (!have_game()) return;
  for (int on = 0; on < 2; ++on) {
    SavedMounts keep;
    zutl::mounts() = zutl::Mounts{};
    zutl::mount(MW3_GAME_DIR);
    zutl::set_write_dir(temp_dir("net_stations"));
    mech3::reset_states();
    reset_process_state();
    mech3::missions() = mech3::Missions{};
    mech3::mech_types_forget();
    mech3::player_controls_instance() = nullptr;
    mech3::options() = mech3::Options{};
    FakeWindow window;
    FakeAlert alert;
    FakeClock clock;
    FakeScreen screen;
    platform::SilentSoundOutput sound;
    mech3::MountFiles files;
    mech3::Platform p;
    p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen,
    p.sound = &sound, p.files = &files;
    znet::Hub hub;
    znet::session() = znet::Session{};
    znet::initialise(hub.endpoint());
    EXPECT(znet::host_session(znet::SessionDesc{}, "Host"));
    int stations = 0, placed = 0, labelled = 0, points = 0;
    {
      mech3::GameEngine engine(p, "mech3.exe -nofmv");
      engine.quiet = true;
      mech3::Mech3App app(&engine);
      mech3::set_app(&app);
      EXPECT(app.init_instance());
      mech3::MultiplayerGame game(nullptr);
      game.x70 = 1 << 30;
      game.ba8 = static_cast<uint8_t>(on);
      mech3::GameEngine::Launch l;
      l.index = 0, l.number = 1, l.type = 3, l.multi = &game;  // c1mp1
      engine.set_launch(l);
      mech3::program_net_debug_lobby();
      app.post_intro_ = &mech3::states().load;
      int core_frames = 0;
      engine.on_present = [&](int) {
        if (app.current() != &mech3::states().core || ++core_frames != 5) return;
        for (int32_t n = 4; n < 40; ++n) {
          char name[32];
          std::snprintf(name, sizeof name, "mfb_station_%02d", n);
          auto* node = static_cast<zcls::Node*>(zcls::list_find_by_name(6, name));
          if (!node) break;
          ++stations;
        }
        int32_t next = 4;
        for (int32_t i = 0; i < 64; ++i) {
          const char* label = nullptr;
          float at[3];
          if (!mech3::program_mission_point(i, &label, at)) continue;
          ++points;
          char want[32];
          std::snprintf(want, sizeof want, "mfb_station_%02d", next);
          if (!label || std::strcmp(label, want) != 0) continue;  // the data's own: 01, 02 on c1mp1
          ++labelled, ++next;
          auto* node = static_cast<zcls::Node*>(zcls::list_find_by_name(6, label));
          float x = 0, y = 0, z = 0;
          if (node) zcls::object3d_get_translation(node, &x, &y, &z);
          const bool in_world = node && node->parent_count() == 1 && node->parents && node->parents[0] == mech3::world_hooks().world;
          if (node && in_world && std::fabs(x - at[0]) < 0.01f && std::fabs(y - at[1]) < 0.01f &&
              std::fabs(z - at[2]) < 0.01f && (node->flags() & 4) != 0)
            ++placed;
        }
      };
      CountingPump pump;
      pump.limit = 2400;
      pump.stop = [&] { return core_frames >= 5; };
      app.run(pump);
      mech3::missions().cleanup(false);
      app.stop_game();
      app.exit_instance();
      mech3::set_app(nullptr);
    }
    znet::shutdown();
    std::printf("  mobile bases %s: %d points, %d stations, %d labelled, %d placed\n", on ? "on" : "off", points, stations,
                labelled, placed);
    EXPECT(points > 0);
    if (on) EXPECT(stations == points && labelled == points && placed == points);
    else EXPECT(stations == 0 && labelled == 0);
    zrdr::close_archives(true);
    mech3::reset_states();
    reset_process_state();
    mech3::options() = mech3::Options{};
  }
}

// The in-game chat (piece 14a): c1mp1 as a network game over the hub; CHAT_ALL
// opens the panel ("CHAT ALL" over the prompt, the game's commands off),
// typing and Enter send 0x1f to all and close it (the commands back), our
// line and a peer's on the HUD ("<name  Send message to all> text", the
// peer's "%s%n" shown as it is, its escape as '?'), an empty line sends
// nothing, CHAT_TEAM outside team play is to all. And (14c) a wreck fades
// out only with ALLOW RESPAWN (the game's +0x8c, 0x0041e220); and the 1.1
// read-me's crash: Bob's respawn and then ours with our panel up, after
// which the keys still type and the commands come back; 1.2's: a burst of
// Shift-letters and '?' into the panel; a weapon's group kept through a
// respawn; outside the boundary, the mech blown up; a kill's score fills
// the objectives box again while it is shown (0x00470170's 0x00446ad0).
TEST(net_chat_panel_c1mp1_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("net_chat_panel"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen,
  p.sound = &sound, p.files = &files;
  mech3::NetChatSeen seen;
  bool ran = false, fade_on = false, fade_off = true, respawn_ran = false;
  mech3::NetChatRespawnSeen rs;
  std::string burst_line;
  mech3::NetGroupsSeen gs;
  bool groups_ran = false, boundary_set = false, box_ran = false;
  mech3::NetScoresBoxSeen box;
  int down_at = 0;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::MultiplayerGame game(nullptr);
    game.x70 = 1 << 30;
    mech3::GameEngine::Launch l;
    l.index = 0, l.number = 1, l.type = 3, l.multi = &game;  // c1mp1
    engine.set_launch(l);
    mech3::program_net_debug_lobby();
    app.post_intro_ = &mech3::states().load;
    int core_frames = 0;
    engine.on_present = [&](int) {
      if (app.current() == &mech3::states().core && ++core_frames == 5) ran = mech3::program_net_chat_check(&seen);
      if (core_frames == 7) respawn_ran = mech3::program_net_chat_respawn_check(&rs);
      if (core_frames == 10) groups_ran = mech3::program_net_groups_check(&gs);
      if (core_frames == 11) box_ran = mech3::program_net_scores_box_check(&box);
      // The read-me's boundary: outside it in a network game the mech blows up
      // (the mp objectives' fail on outside_c1m1, the loss's 0x0048f9e0).
      if (core_frames == 12)
        if (mech3::ai::Valve* v = mech3::ai::valve_find("outside_c1m1")) v->set(1), boundary_set = true;
      if (core_frames > 12 && !down_at) {
        float health = 0, at[3];
        if (!mech3::program_pilot_alive(&health, at)) down_at = core_frames;
      }
      if (core_frames == 8 && mech3::program_chat_open()) {  // the 1.2 read-me's burst, into the panel
        type_burst();
        burst_line = mech3::program_chat_line();
        mech3::program_chat_close();
      }
      if (core_frames == 6) {
        game.b8c = 1;
        fade_on = mech3::program_net_wreck_fades();
        game.b8c = 0;
        fade_off = mech3::program_net_wreck_fades();
        game.b8c = 1;
      }
    };
    CountingPump pump;
    pump.limit = 2400;
    pump.stop = [&] { return core_frames >= 13 + 120 || down_at; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  std::printf("  own: \"%s\"; peer: \"%s\"\n", seen.own.c_str(), seen.peer.c_str());
  EXPECT(ran && seen.opened && seen.prompt_all && seen.commands_off && seen.closed && seen.commands_back);
  EXPECT(seen.sent && seen.own == "<Host  Send message to all> hi there");
  EXPECT(seen.peer == "<Bob  Send message to team> %s%n?[");
  EXPECT(!seen.empty_sent && seen.team_prompt_all);
  EXPECT(seen.hover_kept);  // the mouse over the panel is not its Enter (the console's +0xd0 is line_entered)
  EXPECT(fade_on && !fade_off);
  std::printf("  respawns with the panel up: Bob's %d (panel %d, sent %d, commands %d); ours: closed %d, commands %d, "
              "again %d, sent %d\n", rs.peer_rebuilt, rs.open_after_peer, rs.sent_after_peer, rs.commands_after_peer,
              rs.own_closed, rs.commands_after_own, rs.reopened, rs.sent_after_own);
  EXPECT(respawn_ran && rs.peer_rebuilt && rs.open_after_peer && rs.sent_after_peer && rs.commands_after_peer);
  EXPECT(rs.own_closed && rs.commands_after_own && rs.reopened && rs.sent_after_own);
  std::printf("  burst in the panel: %zu characters \"%.20s...\"\n", burst_line.size(), burst_line.c_str());
  EXPECT(burst_text(burst_line));
  std::printf("  groups: weapon 0 moved %d -> %d, %d after the respawn (%d); weapon 1 %d -> %d\n", gs.moved_from,
              gs.moved_to, gs.after, gs.respawned, gs.other_before, gs.other_after);
  EXPECT(groups_ran && gs.respawned && gs.moved_to != gs.moved_from && gs.after == gs.moved_to);
  EXPECT(gs.other_after == gs.other_before);
  std::printf("  the kill's score: the open box refilled with %d lines (\"%s\"), the closed one %d\n", box.refilled_open,
              box.header.c_str(), box.refilled_closed);
  EXPECT(box_ran && box.refilled_open > 2 && box.header == "Network Game Scores" && box.refilled_closed == 0);
  std::printf("  boundary: outside_c1m1 set %d, the mech down %d frames on\n", boundary_set, down_at ? down_at - 12 : -1);
  EXPECT(boundary_set && down_at > 12);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

// The 1.2 read-me's "your arms no longer flail" and "no longer run in place
// on other players' screens" (14c's checks): c1mp1 as a network game, Bob's
// mech from his 0xf states over the hub. Standing (his place held, no
// throttle) he stands, his arms' aim steady; walking at 10 m/s (throttle
// 0.6) he walks and moves, his arms following his aim as it drifts up;
// stopped dead in the
// stream, his own throttle eases back over about 2 s (the gait follows the
// throttle, not the stream's places), then he stands where he stopped.
// First a ping answer whose delay is past our round trip: his latency 0
// (FIX (bug); unsigned, 2^32 ms, it threw his arms about as he walked).
// The player's death in a campaign mission (14's census items, single
// player): the zoom window locked open (keypad 0); a weapon destroyed plays
// its name and "destroyed" voices (0x004e6dc0 through 0x00571cc0); the head
// lost, the HUD goes off and the window closes, its lock let go
// (0x0041b263..0x0041b30c); none of the three reaches the census.
TEST(mission_c1m1_player_death_hud_and_voices_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("player_death"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen,
  p.sound = &sound, p.files = &files;
  mech3::PlayerDeathSeen seen;
  bool ran = false;
  std::vector<std::string> gaps;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;  // c1m1, a campaign mission
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    int core_frames = 0;
    engine.on_present = [&](int) {
      if (app.current() == &mech3::states().core && ++core_frames == 10) ran = mech3::program_player_death_check(&seen);
    };
    CountingPump pump;
    pump.limit = 3000;
    pump.stop = [&] { return core_frames >= 40; };
    app.run(pump);
    for (const auto& [k, n] : engine.unported_counts())
      if (k == "0x0041b263" || k == "0x004e6dc0" || k == "0x00446ad0") gaps.push_back(k);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  std::printf("  HUD on %d -> %d; the zoom window locked %d -> %d, hidden %d; voices %d of %d; killed %d; census gaps %zu\n",
              seen.hud_before, seen.hud_after, seen.locked_before, seen.locked_after, seen.hidden_after,
              seen.voices_started, seen.voices_wanted, seen.killed, gaps.size());
  EXPECT(ran && seen.killed);
  EXPECT(seen.hud_before == 1 && seen.hud_after == 0);
  EXPECT(seen.locked_before == 1 && seen.locked_after == 0 && seen.hidden_after == 1);
  EXPECT(seen.voices_wanted > 0 && seen.voices_started == seen.voices_wanted);
  EXPECT(gaps.empty());
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

TEST(net_remote_pose_follows_the_states_c1mp1_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("net_remote_pose"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen,
  p.sound = &sound, p.files = &files;
  mech3::NetPoseSeen seen;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::MultiplayerGame game(nullptr);
    game.x70 = 1 << 30;
    mech3::GameEngine::Launch l;
    l.index = 0, l.number = 1, l.type = 3, l.multi = &game;  // c1mp1
    engine.set_launch(l);
    mech3::program_net_debug_lobby();
    app.post_intro_ = &mech3::states().load;
    int core_frames = 0;
    engine.on_present = [&](int) {
      if (app.current() == &mech3::states().core && ++core_frames >= 5) mech3::program_net_pose_step(core_frames - 5, &seen);
    };
    CountingPump pump;
    pump.limit = 3000;
    pump.stop = [&] { return core_frames >= 5 + 241; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  const char* names[3] = {"standing", "walking", "standing again"};
  for (int i = 0; i < 3; ++i) {
    const mech3::NetPoseSeen::Phase& ph = seen.phase[i];
    std::printf("  %s: %d frames, %d at stand, %d walking, arms' aim within %.4f (a frame %.4f), moved %.1f m\n", names[i],
                ph.frames, ph.stand, ph.walking, ph.aim_spread, ph.aim_jump, ph.moved);
  }
  std::printf("  his latency after a ping answer past our round trip: %.4f s\n", seen.latency);
  EXPECT(seen.latency == 0.0f);
  const auto& s0 = seen.phase[0];
  const auto& s1 = seen.phase[1];
  const auto& s2 = seen.phase[2];
  EXPECT(seen.ready && s0.frames == 60 && s1.frames == 90 && s2.frames == 90);
  // Standing: never a step, the arms still once their aim has slerped in.
  EXPECT(s0.stand == s0.frames - 40 && s0.walking == 0 && s0.moved < 0.5f && s0.aim_spread < 0.002f);
  // Walking: a walking gait throughout, the arms following his drifting aim
  // and the walk's lean (about 0.11 rad in all), never a jerk (with the
  // latency's 2^32 ms, 0.03 a frame).
  EXPECT(s1.walking == s1.frames - 15 && s1.moved > 20.0f && s1.aim_spread < 0.2f && s1.aim_jump < 0.01f);
  // Stopped: his throttle eases back (as the owner's, who keeps moving while
  // it does); then he stands where he is.
  EXPECT(s2.stand == s2.frames - 70 && s2.walking == 0 && s2.moved < 1.0f && s2.aim_jump < 0.01f);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

// The same census in a network game (piece 8d: the respawn's hook was null
// and only a soak found it): c1mp1 launched as the soak's debug start does,
// hosting over the hub; at its 60th Core frame every hook hook_allow.txt
// lets be null for "multiplayer:" is set.
TEST(program_hooks_set_in_a_network_game_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("program_hooks_net"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  std::vector<std::string> nulls;
  bool networked = false;
  znet::Hub hub;
  znet::session() = znet::Session{};
  znet::initialise(hub.endpoint());
  EXPECT(znet::host_session(znet::SessionDesc{}, "Host"));
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::MultiplayerGame game(nullptr);
    game.x70 = 1 << 30;
    mech3::GameEngine::Launch l;
    l.index = 0, l.number = 1, l.type = 3, l.multi = &game;  // c1mp1
    engine.set_launch(l);
    mech3::program_net_debug_lobby();
    app.post_intro_ = &mech3::states().load;
    int core_frames = 0;
    engine.on_present = [&](int) {
      if (app.current() == &mech3::states().core && ++core_frames == 60) {
        networked = mech3::program_net_running();
        for (const HookField& h : hook_fields())
          if (h.null()) nulls.push_back(h.name);
      }
    };
    CountingPump pump;
    pump.limit = 2400;
    pump.stop = [&] { return core_frames >= 60; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  znet::shutdown();
  std::map<std::string, std::string> allow;
  if (std::FILE* f = std::fopen(MW3_SOURCE_DIR "/tests/hook_allow.txt", "r")) {
    char buf[512];
    while (std::fgets(buf, sizeof buf, f)) {
      std::string l = buf;
      const size_t tab = l.find('\t');
      if (l.empty() || l[0] == '#' || tab == std::string::npos) continue;
      allow[l.substr(0, tab)] = l.substr(tab + 1);
    }
    std::fclose(f);
  }
  int multiplayer = 0, still_null = 0;
  for (const auto& [n, why] : allow) {
    if (why.rfind("multiplayer: ", 0) != 0) continue;
    ++multiplayer;
    if (std::find(nulls.begin(), nulls.end(), n) != nulls.end()) ++still_null, std::printf("    null in a network game: %s\n", n.c_str());
  }
  std::printf("  a network game (%s): %zu null, %d allowed for multiplayer, %d of them still null\n",
              networked ? "running" : "not running", nulls.size(), multiplayer, still_null);
  EXPECT(networked);
  EXPECT(multiplayer >= 3);  // the crater veto, the anim log's copy, the respawn
  EXPECT(still_null == 0);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

// A mission's vehicles armed (the builder 0x004b4660 with its firepoint
// lookups, 0x004eb0d0 / 0x004abb60) and firing at the player, who goes up to
// each in turn (50 m off) and does not shoot back. Each shot a vehicle's node
// owns spawns at one of its weapons' nodes and is of a weapon it carries
// (+0x80 0: no part, weapons.md, The vehicles' weapons in the program); some
// hit (a vehicle becomes the player's last attacker).
static void vehicles_fire_run(int32_t number) {
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("mission_vehicles_fire"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  int armed = 0, vehicles = 0, weapons = 0, shots = 0, at_firepoint = 0, its_weapon = 0, hits = 0, core_frames = 0,
      attackers = 0;
  float health0 = 0, health = 0;
  std::map<std::string, int> by_vehicle;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;
    l.index = 0, l.number = number;
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    std::set<std::pair<const void*, float>> seen;  // a pool slot and its spawn time
    void* last_attacker = nullptr;
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core) return;
      ++core_frames;
      std::map<const void*, void*> node_vehicle;
      int v_n = 0, a_n = 0, w_n = 0;
      for (const uint32_t h : mech3::ai::entity_list()) {
        void* o = engine.object_of(h);
        if (!mech3::is_program_vehicle(o)) continue;
        ++v_n;
        node_vehicle[mech3::program_vehicle_node(o)] = o;
        if (const int32_t c = mech3::wm_weapon_count(mech3::mech_weapon_manager(o))) ++a_n, w_n += c;
      }
      if (core_frames == 30) vehicles = v_n, armed = a_n, weapons = w_n;
      // The player goes up to each armed vehicle in turn (their sensors reach
      // a few hundred metres; at the start the player is past them).
      if (core_frames % 900 == 60) {
        std::vector<void*> armed_nodes;
        for (const uint32_t h : mech3::ai::entity_list()) {
          void* o = engine.object_of(h);
          if (mech3::is_program_vehicle(o) && mech3::program_vehicle_active(o) &&
              mech3::wm_weapon_count(mech3::mech_weapon_manager(o)))
            armed_nodes.push_back(mech3::program_vehicle_node(o));
        }
        if (!armed_nodes.empty()) mech3::chain_player_near(armed_nodes[static_cast<size_t>(core_frames / 900) % armed_nodes.size()], 50.0f);
      }
      for (zwep::WeaponDef& d : zwep::state().defs)
        for (zwep::Projectile* q = d.active; q; q = q->next) {
          const zwep::Projectile& pr = *q;
          if (pr.state != 1) continue;
          auto it = node_vehicle.find(pr.owner);
          if (it == node_vehicle.end() || !seen.insert({&pr, pr.spawn_at.x + pr.spawn_at.z * 7.0f}).second) continue;
          ++shots;
          by_vehicle[static_cast<const zcls::Node*>(pr.owner)->name()]++;
          void* wm = mech3::mech_weapon_manager(it->second);
          bool from_node = false, carried = false;
          for (int32_t i = 0; i < mech3::wm_weapon_count(wm); ++i) {
            carried |= mech3::wm_weapon_def(wm, i) == &d;
            float fp[3];
            if (zcls::node_world_position(static_cast<zcls::Node*>(mech3::wm_weapon_node(wm, i)), fp) != 0) continue;
            const float dx = fp[0] - pr.spawn_at.x, dy = fp[1] - pr.spawn_at.y, dz = fp[2] - pr.spawn_at.z;
            from_node |= dx * dx + dy * dy + dz * dz < 4.0f;
          }
          at_firepoint += from_node, its_weapon += carried;
        }
      void* attacker = mech3::mech_last_attacker(mech3::mech_mission_player());
      if (attacker && attacker != last_attacker && mech3::is_program_vehicle(attacker)) ++hits;
      if (attacker && attacker != last_attacker) ++attackers;
      last_attacker = attacker;
      if (core_frames == 31) health0 = mech3::mech_health(mech3::mech_mission_player());
      health = mech3::mech_health(mech3::mech_mission_player());
    };
    CountingPump pump;
    pump.limit = 6000;
    pump.stop = [&] { return core_frames >= 5400; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  std::printf("  c1m%d: %d of %d vehicles armed (%d weapons); %d shots by vehicles, %d from a weapon's node, %d of a weapon it carries; %d hits on the player by a vehicle\n",
              number, armed, vehicles, weapons, shots, at_firepoint, its_weapon, hits);
  for (const auto& [n, k] : by_vehicle) std::printf("    %s: %d shots\n", n.c_str(), k);
  std::printf("    the player's health %.3f -> %.3f, %d attackers seen\n", health0, health, attackers);
  EXPECT(armed > 0 && weapons >= armed);
  EXPECT(shots > 0 && at_firepoint == shots && its_weapon == shots);
  EXPECT(hits > 0);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

