// FIX (B), playtest S14: the colour tint's Direct3D quad (the mission's opening
// fade, the hit flashes) gets the 2D canvas's rect; past 640x480 the canvas is
// smaller than the frame, and the fade darkened only its top-left part. The
// rect goes onto the frame as the HUD's panels do.
TEST(fix_tint_quad_covers_the_frame) {
  mech3::Rect& rr = mech3::render();
  mech3::Rect& dr = mech3::display();
  const mech3::Rect saved_r = rr, saved_d = dr;
  const bool saved_fix = zfix::options().any_resolution;
  zfix::options().any_resolution = true;
  mech3::set_render_size(1920, 1080), mech3::set_render_origin(0, 0);
  mech3::set_display_size(960, 540), mech3::set_display_origin(0, 0);
  const int32_t whole[4] = {0, 0, 960, 540}, part[4] = {100, 50, 200, 150};
  mech3::tint_quad_on_frame(0, whole, 0.5);
  const zvid::TintQuad& q = zvid::tint_quad();
  EXPECT(q.verts[0].sx == 0 && q.verts[0].sy == 0 && q.verts[2].sx == 1920 && q.verts[2].sy == 1080);
  mech3::tint_quad_on_frame(0, part, 0.5);
  EXPECT(q.verts[0].sx == 200 && q.verts[0].sy == 100 && q.verts[2].sx == 400 && q.verts[2].sy == 300);
  mech3::set_display_size(1920, 1080);  // a canvas the frame's size: the rect as given
  mech3::tint_quad_on_frame(0, part, 0.5);
  EXPECT(q.verts[0].sx == 100 && q.verts[2].sx == 200 && q.verts[2].sy == 150);
  zvid::reset_tint_quad();
  rr = saved_r, dr = saved_d;
  zfix::options().any_resolution = saved_fix;
}

// Playtest W18 (weapons.md, The AMS): the mech's AMS frame (0x00419200, run
// by the update, 0x0041a822) was a hook nothing set, so no mech's AMS ever
// fired. c1m1's Mad Cat with an AMS on, and off: the same LRM10 salvos fired
// at it from 400 m, hostile to the player (on the radar's list as such). On,
// the AMS shoots missiles down (a round each, the shots gone from the air);
// off, no round spent.
namespace {
struct AmsRun {
  int32_t fitted = 0, rounds_before = 0, rounds_after = 0, fired = 0;
  int32_t in_flight = 0;  // the LRM10s in the air, summed over the frames
};
AmsRun c1m1_ams_run(bool on) {
  AmsRun out;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("mission_c1m1_ams"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  int core = 0;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;  // c1m1
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core) return;
      ++core;
      void* player = mech3::mech_mission_player();
      bool is_on = false;
      if (core == 30) {
        mech3::program_mech_ams_set(player, on);
        mech3::program_mech_ams(player, &out.fitted, &is_on, &out.rounds_before);
      }
      if (zwep::WeaponDef* d = zwep::find_def("LRM10"))
        for (zwep::Projectile* q = d->active; q; q = q->next) ++out.in_flight;
      if (core >= 40 && core <= 400 && core % 60 == 40) out.fired += mech3::program_fire_at(player, "LRM10", 5, 400.0f);
      if (core == 600) {
        mech3::program_mech_ams(player, &out.fitted, &is_on, &out.rounds_after);
      }
    };
    CountingPump pump;
    pump.limit = 100000;
    pump.stop = [&] { return core >= 600; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
  return out;
}
}  // namespace

TEST(mission_c1m1_ams_shoots_down_incoming_missiles_headless) {
  if (!have_game()) return;
  const AmsRun on = c1m1_ams_run(true), off = c1m1_ams_run(false);
  std::printf("  AMS on: %d missiles fired, rounds %d -> %d, %d missile-frames in the air\n", on.fired, on.rounds_before,
              on.rounds_after, on.in_flight);
  std::printf("  AMS off: %d missiles fired, rounds %d -> %d, %d missile-frames in the air\n", off.fired, off.rounds_before,
              off.rounds_after, off.in_flight);
  EXPECT(on.fired == 35 && off.fired == 35);
  EXPECT(on.rounds_after < on.rounds_before);     // missiles shot down, a round each
  EXPECT(off.rounds_after == off.rounds_before);  // none
  EXPECT(on.in_flight < off.in_flight);           // the downed ones gone from the air
}


// Playtest W21: "some of the HUD items are missing" at 16:9 after the
// options' RESOLUTION mid-mission: the weapon names, the speed gauge's ticks
// and numbers, everything past x 640 of the 853x480 canvas. The mode switch
// (0x004ab6b0) locks before it changes, so the 2D target kept the old
// mode's 640x480 (the options') and the freed buffer. The target is the new
// buffer at once, at each switch.
TEST(mission_c1m1_mode_change_moves_the_2d_target_headless) {
  if (!have_game()) return;
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("mode_target_write"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  struct Seen {
    int mode, buf_w, t_w, t_h;
    bool same_base;
  };
  std::vector<Seen> seen;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::options().in_game_vmode = 5;
    mech3::GameEngine::Launch l;
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    int core = 0;
    auto look = [&](int mode) {
      const zrndr::Target2D& t = zrndr::target2d();
      seen.push_back({mode, engine.buffer_width(), static_cast<int>(t.width), static_cast<int>(t.height),
                      t.base == reinterpret_cast<uint8_t*>(engine.buffer16())});
    };
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core) return;
      ++core;
      if (core == 5) engine.set_screen_mode(13), look(13);  // as from the options' 640x480 to 16:9
      if (core == 7) engine.set_screen_mode(5), look(5);
      if (core == 9) engine.set_screen_mode(12), look(12);
    };
    CountingPump pump;
    pump.limit = 900;
    pump.stop = [&] { return core >= 9; };
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  for (const Seen& v : seen)
    std::printf("  mode %d: buffer %d wide, 2D target %dx%d, on the buffer %d\n", v.mode, v.buf_w, v.t_w, v.t_h, v.same_base);
  EXPECT(seen.size() == 3);
  for (const Seen& v : seen) EXPECT(v.t_w == v.buf_w && v.same_base);
  EXPECT(seen.size() == 3 && seen[0].t_w == 853 && seen[0].t_h == 480 && seen[1].t_w == 640);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}


// Playtest W42: the mech lab from the lobby (MECHLAB, 0x0049b500) "lists no
// mechs": the lab's slots came from the campaign and Instant Action only. A
// network game's (vt+0x38 0x004a5270: one; vt+0x34 0x00437800: its +0x20).
TEST(multiplayer_lab_has_the_players_mech_headless) {
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::set_write_dir(temp_dir("mp_lab_write"));
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  mech3::GameEngine engine(p, "mech3.exe -nofmv");
  mech3::Pilot pilot("MP");
  mech3::MultiplayerGame game(&pilot);
  pilot.current = &game;
  mech3::Pilot* was = mech3::current_pilot();
  mech3::current_pilot() = &pilot;
  const int32_t n = engine.lab_slot_count(0);
  const zgame::Handle s0 = engine.lab_slot(0, 0);
  std::printf("  a network game's lab: %d slots, its mech %d; the store %zu items\n", n, s0 ? engine.lab_slot_mech(s0) : -1,
              game.store.items.size());
  EXPECT(n == 1 && s0 && engine.lab_slot_mech(s0) == game.slot.mech && engine.lab_slot(0, 1) == 0);
  // The lab asks the pilot's game (+0x6c) its type (vt+0x2c: the skins hidden
  // in a network game); from the menus, before any launch, it was 0 (W42's
  // "not ported: vt+0x2c( 0 )").
  const zgame::Handle ph = engine.handle_of(&pilot);
  const uint32_t type = engine.vcall(engine.field32(ph, 0x6c), 0x2c, {});
  std::printf("  the pilot's game from the menus: %u\n", type);
  EXPECT(engine.field32(ph, 0x6c) != 0 && type == 3);
  mech3::current_pilot() = was;
  pilot.current = nullptr;
}

// Playtest W37: the mech lab from Instant Action's briefing "shows no mech
// and no ability to edit anything". The lab asks the game for its slots
// (vt+0x38, vt+0x34); the port asked the campaign's only, so Instant
// Action's game (0x00436a30, 0x004368b0) gave none. Its slots now: the
// player's mech first, then the line-up.
TEST(instant_action_lab_has_the_players_mech_headless) {
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::set_write_dir(temp_dir("ia_lab_write"));  // the pilot saves itself
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  mech3::GameEngine engine(p, "mech3.exe -nofmv");
  mech3::Pilot pilot("IA");
  mech3::ActionGame game(&pilot);
  pilot.current = &game;
  game.slot.mech = 9;
  game.add(5, 1, nullptr, 0);   // a lancemate
  game.add(14, 0, nullptr, 0);  // an enemy
  mech3::Pilot* was = mech3::current_pilot();
  mech3::current_pilot() = &pilot;
  const int32_t n = engine.lab_slot_count(0);
  const zgame::Handle s0 = engine.lab_slot(0, 0), s1 = engine.lab_slot(0, 1);
  std::printf("  Instant Action's lab: %d slots, the first's mech %d, the second's %d; the store %zu items\n", n,
              s0 ? engine.lab_slot_mech(s0) : -1, s1 ? engine.lab_slot_mech(s1) : -1, game.store.items.size());
  EXPECT(n == 3 && s0 && engine.lab_slot_mech(s0) == 9 && s1 && engine.lab_slot_mech(s1) == 5);
  mech3::current_pilot() = was;
  pilot.current = nullptr;
}

// Homing in a real fight (playtest: lancemates' LRMs "all over" once their
// target died, or with none; weapons.md, Homing). c3m5 with the lance and
// the player put 300 m from the first enemies, every live shot of every
// projectile weapon watched each frame (a retired slot keeps state 1 in the
// pool: the active lists are read). Optionally the mech a lancemate's first
// locked salvo is on is killed 10 frames after the launch.
namespace {
struct HomingRun {
  int frames = 0, locked = 0, unlocked = 0;
  int wrong_entity = 0;       // locked on another than the shooter's selected target
  int off_at_launch = 0;      // launched over 10 degrees off its aim (the part's facing, out of its cone)
  int jumps = 0, away = 0, garbage = 0;  // aim moved over 30 m in a frame, over 60 m from its target, not finite
  int unlocked_turns = 0;     // an unlocked shot's direction changed
  int unlocked_with_aim = 0;  // a shot without a lock entity that has an aim point
  int probes = 0, grounded = 0, under = 0;  // ground probes under flying shots; found; found above the shot
  int zone_border = 0;        // of those not found, over ground in a zone outside the shot's set (the original's zones)
  bool killed = false;
  bool player_had_target = true;
  int player_shots = 0, player_locked = 0, player_turns = 0;  // the player's LRMs fired at frame 30 with no target
  int salvo = 0, salvo_reached = 0;  // the killed mech's salvo in flight: shots, and those that came within 10 m of the wreck's aim
  float worst_reach = 0;
};

// A shot's direction changed between frames: by angle, the directions
// normalised (a direction from an eased aim is not quite unit length, W50).
bool turned(const zwep::Vec3f3& a, const zwep::Vec3f3& b) {
  const float la = std::sqrt(a.x * a.x + a.y * a.y + a.z * a.z), lb = std::sqrt(b.x * b.x + b.y * b.y + b.z * b.z);
  return !(la > 0.0f && lb > 0.0f) || (a.x * b.x + a.y * b.y + a.z * b.z) / (la * lb) < 0.9999f;
}

HomingRun homing_run(const char* dir, bool kill, int limit) {
  HomingRun r;
  std::map<void*, void*> last_target, prev_target;  // the AI mechs' targets, this frame and the one before
  SavedMounts keep;
  const zfix::Options fix_was = zfix::options();
  zfix::options() = zfix::Options{};  // play's switches, whatever a test before left
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(dir);
  zutl::set_write_dir(temp_dir("homing_write"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  struct Keys : platform::Input {  // the player's LRMs fired once with no target selected
    std::vector<platform::KeyEvent> queue;
    uint32_t t = 0;
    void key(uint32_t dik, bool down) { queue.push_back({dik, down ? 0x80u : 0u, ++t, t}); }
    bool open(Device d) override { return d == kKeyboard; }
    void close(Device) override {}
    int32_t acquire(Device) override { return 0; }
    int32_t unacquire(Device) override { return 0; }
    int32_t keyboard_data(platform::KeyEvent* out, uint32_t* count) override {
      const uint32_t n = std::min<uint32_t>(*count, static_cast<uint32_t>(queue.size()));
      std::copy(queue.begin(), queue.begin() + n, out);
      queue.erase(queue.begin(), queue.begin() + n);
      *count = n;
      return 0;
    }
    int32_t mouse_state(platform::MouseState*) override { return kNotAcquired; }
    int32_t joystick_state(platform::JoyState*) override { return kNotAcquired; }
  } keys;
  p.input = &keys;
  auto flying = [] {
    std::vector<const zwep::Projectile*> out;
    for (const zwep::WeaponDef& d : zwep::state().defs)
      if (!(d.flags & zwep::kBeam))  // a beam def's list holds beams
        for (const zwep::Projectile* q = d.active; q; q = q->next) out.push_back(q);
    return out;
  };
  struct Track { zwep::Vec3f3 at{}, dir{}, spawn{}; bool have = false; float reach = 1e9f; bool in_salvo = false, player = false; int frames_seen = 0; };
  std::map<const zwep::Projectile*, Track> seen;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;
    l.index = 2, l.number = 5;
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    void *player = nullptr, *victim = nullptr;
    int fired_at = -1;
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core) return;
      ++r.frames;
      int32_t made = 0;
      const mech3::AiMechMade* ai = mech3::mission_ai_mechs(&made);
      if (r.frames == 5) {
        player = engine.object_of(engine.field32(engine.pilot(), 0x14));
        mech3::LaunchedMech me, e0;
        mech3::describe_mech(player, &me);
        mech3::describe_mech(ai[0].mech, &e0);
        int n = 0;
        for (int32_t k = 0; k < made; ++k) {
          mech3::LaunchedMech o;
          mech3::describe_mech(ai[k].mech, &o);
          if (o.team != me.team) continue;
          const float x = e0.pos[0] + 300.0f, z = e0.pos[2] + 30.0f * n++;
          const float at[3] = {x, ground_under(x, e0.pos[1] + 120.0f, z), z};
          mech3::move_mech(ai[k].mech, at, -1.5707964f);
        }
        const float x = e0.pos[0] + 340.0f, z = e0.pos[2];
        const float at[3] = {x, ground_under(x, e0.pos[1] + 120.0f, z), z};
        mech3::move_mech(player, at, -1.5707964f);
      }
      if (r.frames < 5) return;
      static uint32_t fire = 0;
      if (r.frames == 30) {
        for (int32_t g = 0; g < 5; ++g)
          if (mech3::mech_group_names(player, g).find("LRM") != std::string::npos) {
            mech3::mech_select_group(player, g);
            break;
          }
        r.player_had_target = mech3::mech_target_object(player) != nullptr;
        fire = zin::key1_of(0x3d) & 0xff;  // CMD_FIRE
        keys.key(fire, true);
      }
      if (r.frames == 31) keys.key(fire, false);
      // The shooters' targets a frame before: one may fire, then pick a new
      // target in the same update (the shot is first seen after both).
      prev_target = last_target;
      for (int32_t k = 0; k < made; ++k) last_target[ai[k].mech] = mech3::mech_target_object(ai[k].mech);
      const auto live = flying();
      for (auto it = seen.begin(); it != seen.end();) {
        if (std::find(live.begin(), live.end(), it->first) != live.end()) {
          ++it;
          continue;
        }
        if (it->second.in_salvo) {  // the killed mech's salvo: did it reach the wreck
          ++r.salvo;
          if (it->second.reach <= 10.0f) ++r.salvo_reached;
          r.worst_reach = std::max(r.worst_reach, it->second.reach);
        }
        it = seen.erase(it);
      }
      // The first locked salvo of a lancemate on an AI mech: its target killed 10 frames on.
      if (kill && fired_at < 0)
        for (const zwep::Projectile* q : live)
          for (int32_t k = 0; k < made && fired_at < 0; ++k)
            if (q->target_at && q->owner != mech3::mech_node(player) && ai[k].mech == q->lock_entity) fired_at = r.frames, victim = ai[k].mech;
      if (kill && fired_at > 0 && r.frames == fired_at + 10) {
        mech3::mech_kill(victim, nullptr);
        r.killed = true;
        for (const zwep::Projectile* q : live)
          if (q->target_at && q->lock_entity == victim) seen[q].in_salvo = true;
      }
      for (const zwep::Projectile* q : live) {
        const zwep::Projectile& s = *q;
        Track& t = seen[q];
        if (t.have && (t.spawn.x != s.spawn_at.x || t.spawn.y != s.spawn_at.y || t.spawn.z != s.spawn_at.z)) t = Track{};
        t.spawn = s.spawn_at;
        const zwep::Vec3f3 d = s.direction;
        if (zwep::run_hooks().ground && s.speed > 0.0f) {
          zwep::HitList g;
          uint8_t zones[4];  // the shot's zone set, as the update sets it around its probe (0x00585710)
          std::memcpy(zones, zmod::zones().list, 4);
          if ((s.zone & 0xff) != 4) std::memcpy(zmod::zones().list, &s.zone, 4);
          zwep::run_hooks().ground(&s.position, &g);
          ++r.probes;
          if (!g.count) {  // allowed only where the ground there is in a zone the shot's set leaves out
            const int32_t mode = zmod::zones().mode;
            zmod::zones().mode = 0;
            zwep::HitList all;
            zwep::run_hooks().ground(&s.position, &all);
            zmod::zones().mode = mode;
            const uint8_t* zs = reinterpret_cast<const uint8_t*>(&s.zone);
            bool in_set = false;
            if (all.count && all.rec[0].node)
              for (int k = 1; k <= zs[0] && k < 4; ++k) in_set |= zs[k] == static_cast<zcls::Node*>(all.rec[0].node)->raw[0x30];
            if (all.count && !in_set) ++r.zone_border;
          }
          if (!g.count && std::getenv("MW3_HOMING_VERBOSE"))
          {
            zwep::Vec3f3 hi = s.position;
            hi.y += 100.0f;
            zwep::HitList g2;
            zwep::run_hooks().ground(&hi, &g2);
            const int32_t mode = zmod::zones().mode;
            zmod::zones().mode = 0;
            zwep::HitList g3;
            zwep::run_hooks().ground(&s.position, &g3);
            zmod::zones().mode = mode;
            std::printf("    no ground under a shot at %.1f %.1f %.1f (frame %d, zones %08x); from 100 m higher: %d; zones off: %d %.1f %s zone %d\n", s.position.x,
                        s.position.y, s.position.z, r.frames, s.zone, g2.count, g3.count, g3.count ? g3.rec[0].point.y : 0.0f,
                        g3.count && g3.rec[0].node ? static_cast<zcls::Node*>(g3.rec[0].node)->name() : "-",
                        g3.count && g3.rec[0].node ? static_cast<zcls::Node*>(g3.rec[0].node)->raw[0x30] : -1);
          }
          if (g.count) {
            ++r.grounded;
            if (g.rec[0].point.y > s.position.y + 0.5f) ++r.under;
          }
          std::memcpy(zmod::zones().list, zones, 4);
        }
        if (!t.have && s.owner == mech3::mech_node(player) && r.frames <= 120) ++r.player_shots, t.player = true;
        if (t.player && s.target_at) ++r.player_locked;
        if (t.player) {
          t.frames_seen++;
          if (t.have && turned(d, t.dir)) ++r.player_turns;
        }
        if (!s.target_at) {
          if (!t.have) ++r.unlocked;
          else if (turned(d, t.dir)) ++r.unlocked_turns;
          t.dir = d, t.have = true;
          continue;
        }
        if (!s.lock_entity) ++r.unlocked_with_aim;
        const zwep::Vec3f3 at = *s.target_at;
        if (!std::isfinite(at.x) || !std::isfinite(at.y) || !std::isfinite(at.z) || std::fabs(at.x) > 1e5f ||
            std::fabs(at.y) > 1e5f || std::fabs(at.z) > 1e5f) {
          ++r.garbage;
          t.have = true;
          continue;
        }
        const float wx = at.x - s.position.x, wy = at.y - s.position.y, wz = at.z - s.position.z;
        const float wl = std::sqrt(wx * wx + wy * wy + wz * wz);
        if (!t.have) {
          ++r.locked;
          // The lock is the shooter's selected target (+0x6c's object): what
          // the shot leaves toward may differ, a part's weapon firing along
          // its facing when the target is over 27 degrees off (0x004b36e0).
          void* shooter = s.owner == mech3::mech_node(player) ? player : nullptr;
          for (int32_t k = 0; k < made && !shooter; ++k)
            if (mech3::mech_node(ai[k].mech) == s.owner) shooter = ai[k].mech;
          if (shooter && mech3::mech_target_object(shooter) != s.lock_entity && prev_target[shooter] != s.lock_entity)
            ++r.wrong_entity;
          if (wl > 1.0f && (wx * d.x + wy * d.y + wz * d.z) / wl < std::cos(10.0f / 57.29578f)) ++r.off_at_launch;
        } else {
          const float dx = at.x - t.at.x, dy = at.y - t.at.y, dz = at.z - t.at.z;
          if (dx * dx + dy * dy + dz * dz > 30.0f * 30.0f) ++r.jumps;
        }
        if (s.lock_entity) {
          float e[3];
          mech3::hud_object_place(s.lock_entity, e);
          const float dx = at.x - e[0], dy = at.y - e[1], dz = at.z - e[2];
          if (dx * dx + dy * dy + dz * dz > 60.0f * 60.0f) ++r.away;
        }
        t.reach = std::min(t.reach, wl);
        t.at = at, t.dir = d, t.have = true;
      }
    };
    CountingPump pump;
    pump.stop = [&] { return r.frames >= limit; };
    pump.limit = limit + 3000;
    app.run(pump);
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
  zfix::options() = fix_was;
  return r;
}

void print_homing(const char* what, const HomingRun& r) {
  std::printf("  %s: %d frames, %d locked shots (%d on another entity, %d aims jumped, %d away, %d garbage), %d unlocked "
              "(%d turned, %d with an aim); %d launched off their aim; ground under %d of %d shots (%d above them, %d over another zone's ground)",
              what, r.frames, r.locked, r.wrong_entity, r.jumps, r.away, r.garbage, r.unlocked, r.unlocked_turns,
              r.unlocked_with_aim, r.off_at_launch, r.grounded, r.probes, r.under, r.zone_border);
  std::printf("; the player's free salvo: %d shots (target %d), %d locked, %d turns", r.player_shots, r.player_had_target, r.player_locked, r.player_turns);
  if (r.killed) std::printf("; the killed mech's salvo: %d of %d shots reached the wreck (worst %.1f m)", r.salvo_reached, r.salvo, r.worst_reach);
  std::printf("\n");
}

void expect_homing(const HomingRun& r) {
  EXPECT(r.locked > 20 && r.unlocked > 50);  // the fight happened
  EXPECT(r.wrong_entity == 0 && r.jumps == 0 && r.away == 0 && r.garbage == 0);
  EXPECT(r.unlocked_turns == 0 && r.unlocked_with_aim == 0);
  EXPECT(!r.player_had_target && r.player_shots >= 2 && r.player_locked == 0 && r.player_turns == 0);  // no target: straight
  EXPECT(r.probes > 1000 && r.grounded + r.zone_border == r.probes && r.under == 0);
}

// The 1.0 install beside the 1.2 one (game/mw3-1.0), when there is one.
std::string homing_dir_10() {
  const std::filesystem::path d = std::filesystem::path(MW3_GAME_DIR).parent_path() / "mw3-1.0";
  return std::filesystem::exists(d / "zbd") ? d.string() : std::string();
}
}  // namespace

// The fight on 1.2: every lock on what was fired at, its aim on the target
// (a live pointer into the target node's world matrix) and finite; the
// unlocked shots straight; the ground found under every flying shot.
TEST(mission_c3m5_homing_in_a_fight_headless) {
  if (!have_game()) return;
  const HomingRun r = homing_run(MW3_GAME_DIR, false, 9000);
  print_homing("1.2", r);
  expect_homing(r);
}

// The target of a lancemate's LRM salvo killed mid-flight: the aim stays on
// the wreck (the node stays, as the original's), and the salvo reaches it.
TEST(mission_c3m5_homing_target_killed_headless) {
  if (!have_game()) return;
  const HomingRun r = homing_run(MW3_GAME_DIR, true, 3000);
  print_homing("1.2, killed", r);
  EXPECT(r.killed && r.salvo >= 2 && r.salvo_reached == r.salvo);
  EXPECT(r.jumps == 0 && r.away == 0 && r.garbage == 0 && r.unlocked_turns == 0);
}

// The same on the 1.0 data (c3's world rebuilt by our 1.0 layer, W48: the
// models' types and boxes; the ground probe under the shots sees them).
TEST(mission_c3m5_homing_on_10_data_headless) {
  if (!have_game()) return;
  const std::string d = homing_dir_10();
  if (d.empty()) return;
  const HomingRun r = homing_run(d.c_str(), true, 9000);
  print_homing("1.0, killed", r);
  expect_homing(r);
  EXPECT(r.killed && r.salvo >= 2 && r.salvo_reached == r.salvo);
}

// Reddit, v1.0 ("I can't seem to make custom keyboard binds?"): the controls
// screen's capture driven as a player does, through the fake keyboard and
// mouse (zInput's own buffer, the path a mission's keys take): a row's key A
// clicked, a free key pressed and let go; a key another command has (the
// Reassign Key box, answered OK); the mouse column and a button; ACCEPT (the
// save-to-file question answered no); then a restart reads them back.
namespace {
struct RebindInput : platform::Input {
  std::vector<platform::KeyEvent> queue;
  uint32_t t = 0;
  uint8_t buttons[4] = {};
  void press(uint32_t dik) {
    queue.push_back({dik, 0x80u, ++t, t});
    queue.push_back({dik, 0u, ++t, t});
  }
  void press_with(uint32_t mod, uint32_t dik) {
    queue.push_back({mod, 0x80u, ++t, t});
    press(dik);
    queue.push_back({mod, 0u, ++t, t});
  }
  bool open(Device d) override { return d == kKeyboard || d == kMouse; }
  void close(Device) override {}
  int32_t acquire(Device) override { return 0; }
  int32_t unacquire(Device) override { return 0; }
  int32_t keyboard_data(platform::KeyEvent* out, uint32_t* count) override {
    const uint32_t n = std::min<uint32_t>(*count, static_cast<uint32_t>(queue.size()));
    std::copy(queue.begin(), queue.begin() + n, out);
    queue.erase(queue.begin(), queue.begin() + n);
    *count = n;
    return 0;
  }
  int32_t mouse_state(platform::MouseState* m) override {
    *m = platform::MouseState{};
    std::memcpy(m->buttons, buttons, 4);
    return 0;
  }
  int32_t joystick_state(platform::JoyState*) override { return kNotAcquired; }
};
}  // namespace

TEST(reddit_controls_screen_rebinds_through_the_keyboard_headless) {
  if (!have_game()) return;
  W40Setup w("rebind_write");
  RebindInput in;
  int stage = 0, wait = 0, box_frames = 0, boxes = 0;
  int32_t cmd0 = 0, cmd1 = 0, cmd2 = 0, cmd3 = 0, esc_holder = -1;
  uint32_t free_key = 0, free_key2 = 0, old_key1 = 0, mouse_was = 0, key3 = 0, shift_f1 = 0;
  bool bound = false, reassigned = false, moused = false, early_ignored = false, esc_cancelled = false;
  bool esc_left = false, shifted = false;
  const std::vector<uint8_t> saved = w40_run(w.dir, nullptr, nullptr, [&](mech3::GameEngine& engine, mech3::Mech3App& app) {
    if (ztwod::MessageBox* box = engine.message_box_open()) {  // Reassign Key (OK), then ACCEPT's save question (no)
      if (++box_frames == 3) {
        ++boxes;
        box->buttons[stage == 7 ? 1 : 0].on_left_up();
        box_frames = 0;
      }
      return false;
    }
    auto* os = dynamic_cast<mech3::OptionsState*>(app.current());
    auto* c = os ? dynamic_cast<mech3::ControlsScreen*>(engine.screen_of(os->screen_)) : nullptr;
    if (stage == 0 && at_main_menu(app)) {
      const_cast<mech3::MainMenu*>(mech3::main_menu())->buttons[mech3::MainMenuButton::kOptions].on_left_up();
      stage = 1;
    } else if (stage == 1 && os) {
      auto* g = dynamic_cast<mech3::GameOptionsScreen*>(engine.screen_of(os->screen_));
      if (!g) return false;
      g->controls.on_left_up();
      stage = 2;
    } else if (stage == 2 && c) {
      cmd0 = engine.controls_group_command(c->group(), 0);
      cmd1 = engine.controls_group_command(c->group(), 1);
      cmd2 = engine.controls_group_command(c->group(), 2);
      for (uint32_t k = 0x02; k < 0x58; ++k)
        if (!engine.key1_command(k) && !engine.key2_command(k)) {
          if (!free_key) free_key = k;
          else if (!free_key2) free_key2 = k;
        }
      cmd3 = engine.controls_group_command(c->group(), 3);
      old_key1 = zin::key1_of(cmd1);
      c->key_a.select(0), c->key_a.on_left_up();  // row 0's key A clicked (down: the row; up: the capture)
      stage = 3, wait = 0;
    } else if (stage == 3 && c) {
      if (++wait == 3) in.press(free_key);
      if (zin::key1_of(cmd0) == free_key) bound = true, stage = 4, wait = 0;
      if (wait > 60) return true;
    } else if (stage == 4 && c) {
      if (++wait == 3) c->key_a.select(1), c->key_a.on_left_up();  // row 1: the key row 0 now has
      if (wait == 6) in.press(free_key);
      if (zin::key1_of(cmd1) == free_key) {
        reassigned = boxes == 1 && zin::key1_of(cmd0) == 0;
        stage = 5, wait = 0;
      }
      if (wait > 60) return true;
    } else if (stage == 5 && c) {
      if (++wait == 12) mouse_was = zin::mouse_of(cmd2), c->mouse.select(2), c->mouse.on_left_up();  // past the guard
      if (wait >= 15 && wait < 20) in.buttons[2] = 0x80;  // the middle button (3) held, then let go
      if (wait == 20) in.buttons[2] = 0;
      if (zin::mouse_of(cmd2) == 3) moused = true, stage = 6, wait = 0;
      if (wait > 80) return true;
    } else if (stage == 6 && !c) {  // Escape left the screen at once
      if (wait >= 25) {
        esc_cancelled = zin::key1_of(cmd3) == key3 && engine.key1_command(1) == esc_holder;
        stage = 61, wait = 0;
      }
    } else if (stage == 6 && c) {
      // A key that went down in the frame's read before the column's click
      // (the click routed in that frame's update, which then asks): not bound.
      ++wait;
      if (wait == 11) in.press(free_key2), key3 = zin::key1_of(cmd3);
      if (wait == 12) c->key_a.select(3), c->key_a.on_left_up(), c->update(0.0f);
      if (wait == 24) early_ignored = c->mode == 1 && zin::key1_of(cmd3) == key3 && !engine.key1_command(free_key2);
      // Escape in the capture: cancelled (the key 1), not bound.
      if (wait == 25) esc_holder = engine.key1_command(1), in.press(0x01);
      if (wait == 28) {
        esc_cancelled = c->mode == 0 && zin::key1_of(cmd3) == key3 && engine.key1_command(1) == esc_holder;
        stage = 61, wait = 0;
      }
    } else if (stage == 61 || stage == 62) {  // Escape may leave the screen, as the shell's escape does
      auto* g = os ? dynamic_cast<mech3::GameOptionsScreen*>(engine.screen_of(os->screen_)) : nullptr;
      if (stage == 61 && !c) {
        esc_left = true;
        if (g) g->controls.on_left_up();
        if (g) stage = 62;
        return ++wait > 60;
      }
      if (!c) return ++wait > 60;
      stage = 63, wait = 0;
    } else if (stage == 63 && c) {
      // Shift+F1: the modifier with the key, as 0x0051aa00 gives it.
      if (++wait == 3) c->key_a.select(3), c->key_a.on_left_up();
      if (wait == 6) in.press_with(0x2a, 0x3b);
      if (zin::key1_of(cmd3) == (0x3bu | zin::kShift)) shifted = true, shift_f1 = zin::key1_of(cmd3), stage = 64, wait = 0;
      if (wait > 60) return true;
    } else if (stage == 64 && c) {
      if (++wait == 12) stage = 7, c->accept.on_left_up();  // its box runs inside: answered as stage 7
    } else if (stage == 7 && !c) {
      return true;
    }
    return false;
  }, &in);
  std::printf("  rebind: key %#x on %#x, reassigned to %#x (was %#x), mouse 3 on %#x (was %u), %d boxes, stage %d\n",
              free_key, cmd0, cmd1, old_key1, cmd2, mouse_was, boxes, stage);
  EXPECT(free_key != 0 && bound);
  EXPECT(reassigned);
  EXPECT(moused);
  std::printf("  rebind: early key ignored %d, Escape cancelled %d (left the screen %d), Shift+F1 %#x\n", early_ignored,
              esc_cancelled, esc_left, shift_f1);
  EXPECT(early_ignored);
  EXPECT(esc_cancelled);
  EXPECT(shifted);
  EXPECT(stage == 7 && boxes >= 2);
  bool kept = false;
  w40_run(w.dir, nullptr, [&] {
    kept = zin::key1_of(cmd1) == free_key && zin::key1_of(cmd0) == 0 && zin::mouse_of(cmd2) == 3 &&
           zin::key1_of(cmd3) == (0x3bu | zin::kShift);
  }, [](mech3::GameEngine&, mech3::Mech3App& app) { return at_main_menu(app); });
  EXPECT(kept);  // read back at the next start
  EXPECT(!saved.empty());
}
// Playtest W50 (Owen, c1m2 on the Mac, v1.0): "Destroy Missile Platforms
// OP: Baker" stays In Progress; triturret02 vanished with no wreck while its
// triangle and target box (empty) stayed. The tripod turrets start facing
// straight up (their node's rotation, normalised); their first aim eases the
// facing by e^-(3 dt) through zMath's table, which reads 1 on frames shorter
// than 6.5 ms, so the facing stays vertical, its flat part 0, and the exe's
// bit-trick square root of 0 (8e-20) takes the heading branch with c = -0,
// sn = 0: the turret's matrix loses its yaw axes and the turret and gun are
// drawn flat. Here c1m2's triturret02 aims at the player 35 m off, at 6 ms
// and 33 ms frames, with the fixes and without.
namespace {
struct AimRun {
  float facing_y = 0;  // after the aim
  float yaw_det = 0;   // the turret matrix's x and z axes: 1 a rotation, 0 collapsed
};
}  // namespace

TEST(mission_c1m2_triturret_aim_on_fast_frames_headless) {
  SavedMounts keep;
  zutl::mounts() = zutl::Mounts{};
  zutl::mount(MW3_GAME_DIR);
  zutl::set_write_dir(temp_dir("mission_w50_write"));
  mech3::reset_states();
  reset_process_state();
  mech3::missions() = mech3::Missions{};
  mech3::mech_types_forget();
  mech3::player_controls_instance() = nullptr;
  mech3::options() = mech3::Options{};
  const zfix::Options fixes_was = zfix::options();
  FakeWindow window;
  FakeAlert alert;
  FastClock clock;
  FakeScreen screen;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  bool ran = false;
  {
    mech3::GameEngine engine(p, "mech3.exe -nofmv");
    engine.quiet = true;
    mech3::Mech3App app(&engine);
    mech3::set_app(&app);
    EXPECT(app.init_instance());
    mech3::GameEngine::Launch l;
    l.index = 0, l.op = 1, l.number = 2;  // c1m2
    engine.set_launch(l);
    app.post_intro_ = &mech3::states().load;
    mech3::Pilot pilot("W50");
    mech3::Game game(&pilot);
    pilot.current = &game;
    mech3::Pilot* was_pilot = mech3::current_pilot();
    mech3::current_pilot() = &pilot;
    int frames = 0;
    engine.on_present = [&](int) {
      if (app.current() != &mech3::states().core || ++frames != 30) return;
      mech3::tur::Turret* t = nullptr;
      for (const mech3::ChainTarget& c : mech3::chain_hostiles())
        if (c.name == "triturret02") t = mech3::program_turret_by_handle(c.h);
      EXPECT(t != nullptr);
      if (!t) return;
      auto* tn = static_cast<zcls::Node*>(engine.object_of(t->turret));
      float* tm = tn ? zcls::object3d_matrix(tn) : nullptr;
      EXPECT(tm != nullptr);
      if (!tm) return;
      EXPECT(t->facing[0] == 0.0f && t->facing[1] == 1.0f && t->facing[2] == 0.0f);  // straight up, as made
      float tm0[12], f0[3];
      std::memcpy(tm0, tm, sizeof tm0), std::memcpy(f0, t->facing, sizeof f0);
      float at[3] = {};
      const mech3::Handle h = engine.handle_of(at);
      auto aim = [&](float dt, bool per_second, bool bugs) {
        std::memcpy(t->facing, f0, sizeof f0);
        zcls::object3d_set_matrix(tn, tm0);
        zfix::options().per_second = per_second, zfix::set_all(bugs);
        mech3::program_turret_dt(dt);
        t->aim(h);
        const float* m = zcls::object3d_matrix(tn);
        AimRun r;
        r.facing_y = t->facing[1];
        r.yaw_det = m[0] * m[8] - m[2] * m[6];
        return r;
      };
      // From 8 sides, 35 m off and 6 m up (Owen's place in his shot is one).
      int fixed_turned = 0, original_collapsed = 0, table_collapsed = 0, slow_collapsed = 0, fixed_collapsed = 0;
      for (int k = 0; k < 8; ++k) {
        const float a = 0.785398f * static_cast<float>(k);
        at[0] = t->pos[0] + 35.0f * std::cos(a), at[1] = t->pos[1] + 6.0f, at[2] = t->pos[2] + 35.0f * std::sin(a);
        const AimRun fixed = aim(0.006f, true, true), original = aim(0.006f, false, false),
                     table = aim(0.006f, false, true), slow = aim(0.033f, false, false);
        std::printf("  side %d: fixed facing y %.4f det %.3f | exe 6 ms %.4f %.3f | yaw fix alone %.4f %.3f | exe 33 ms %.4f %.3f\n",
                    k, fixed.facing_y, fixed.yaw_det, original.facing_y, original.yaw_det, table.facing_y, table.yaw_det,
                    slow.facing_y, slow.yaw_det);
        auto collapsed = [](const AimRun& r) { return std::fabs(r.yaw_det) < 0.5f; };
        fixed_turned += fixed.facing_y < 1.0f;
        fixed_collapsed += collapsed(fixed), original_collapsed += collapsed(original);
        table_collapsed += collapsed(table), slow_collapsed += collapsed(slow);
      }
      std::memcpy(t->facing, f0, sizeof f0);
      zcls::object3d_set_matrix(tn, tm0);
      // The exe at 166 fps: no easing, and every side collapses the yaw (what Owen saw).
      EXPECT(original_collapsed == 8);
      // Fixed: never collapsed, and it turns toward the sides its limits allow.
      EXPECT(fixed_collapsed == 0 && fixed_turned > 0);
      // The yaw fix alone (the table's no easing yet): still drawn.
      EXPECT(table_collapsed == 0);
      // The exe at its 30 fps eases off vertical before the matrix: never collapsed.
      EXPECT(slow_collapsed == 0);
      ran = true;
    };
    CountingPump pump;
    pump.limit = 2000;
    pump.stop = [&] { return frames >= 30; };
    app.run(pump);
    mech3::current_pilot() = was_pilot;
    pilot.current = nullptr;
    mech3::missions().cleanup(false);
    app.stop_game();
    app.exit_instance();
    mech3::set_app(nullptr);
  }
  zfix::options() = fixes_was;
  EXPECT(ran);
  zrdr::close_archives(true);
  mech3::reset_states();
  reset_process_state();
  mech3::options() = mech3::Options{};
}

// Playtest W55 (Owen, PC; the Mac too): MECH LAB, VARIANTS, SAVE over a
// variant of his own, Enter: "Overwrite?" over a purple screen. The lab's
// frame goes through the GPU, the 16-bit buffer holding only its 2D layer;
// the message box (0x004ac150) first locks and unlocks the 3D layer empty,
// and that unlock counted as a layer drawn, so the box's first flip dropped
// the lab's held frame (W25) and showed the buffer, the layer's key colour
// (magenta), as the screen. Here a GPU frame with a layer, then the box's
// empty lock, the hold and the box's flip: the kept frame back, the buffer
// not shown as the screen.
TEST(message_box_over_a_gpu_frame_keeps_it_after_an_empty_lock) {
  struct HoldGpu : platform::Render3D {
    int presents = 0, holds = 0, restores = 0;
    int32_t create_texture(int, int, const uint8_t*, uint8_t) override { return 1; }
    void release_texture(int32_t) override {}
    void update_texture(int32_t, int, int, const uint8_t*) override {}
    void set_viewport(int, int, int, int) override {}
    void clear(bool, uint8_t, uint8_t, uint8_t) override {}
    void begin_scene() override {}
    void end_scene() override {}
    void draw(platform::Primitive, const platform::TLVertex*, int, const platform::DrawState&) override {}
    void set_fog_color(uint8_t, uint8_t, uint8_t) override {}
    void present() override { ++presents; }
    bool hold_frame() override { return ++holds, true; }
    bool restore_frame() override { return ++restores, true; }
  } gpu;
  struct CountScreen : platform::Screen2D {
    int as_screen = 0, overlays = 0;
    void present_16(const uint16_t*, int, int, int, bool) override { ++as_screen; }
    void overlay_16(const uint16_t*, int, int, int, bool, uint16_t, const uint8_t*, const uint16_t*) override { ++overlays; }
  } screen;
  FakeWindow window;
  FakeAlert alert;
  FakeClock clock;
  platform::SilentSoundOutput sound;
  mech3::MountFiles files;
  mech3::Platform p;
  p.window = &window, p.alert = &alert, p.clock = &clock, p.movie_clock = &fast_movie_clock(), p.screen = &screen, p.sound = &sound, p.files = &files;
  p.render = &gpu;
  mech3::GameEngine e(p, "mech3.exe -nofmv");
  zvid::Surface s;
  // The lab's frame: its 2D layer drawn over the key, through the GPU.
  e.lock_back(&s);
  s.pixels[0] = 0x1234;
  e.unlock_back(&s);
  e.video_flip(0, 0, 0, 0);
  EXPECT(gpu.presents == 1 && screen.as_screen == 0);
  // The box: its empty lock and unlock, the frame held (its backdrop), its frames.
  e.lock_back(&s);
  e.unlock_back(&s);
  EXPECT(e.hold_shown_frame());
  for (int k = 0; k < 3; ++k) e.video_flip(0, 0, 0, 0);
  std::printf("  held %d, restores %d, presents %d, buffer shown as the screen %d\n", e.held(), gpu.restores, gpu.presents,
              screen.as_screen);
  EXPECT(e.held() && gpu.restores == 3 && gpu.presents == 4 && screen.as_screen == 0);
  e.drop_held();
}

// W56 (ours, FIX (bug) behind bugs): the axis popup offers the stick's
// sliders (0x00430180 never did: a T.16000M's lever could not be picked),
// and OK on the throttle binds it stop-to-full as the defaults do, whatever
// the lever's place at OK (the lever map then gives reverse); a slider scaled
// from DirectInput's 0..65535.
TEST(controls_axis_popup_binds_a_slider_to_the_throttle_headless) {
  if (!have_game()) return;
  for (const bool bugs : {true, false}) {
    W40Setup w(bugs ? "popup_slider_write" : "popup_slider_off_write");
    zfix::set_all(bugs);
    int stage = 0, wait = 0;
    bool listed = false;
    mech3::AxisBinding bound;
    w40_run(w.dir, nullptr, nullptr, [&](mech3::GameEngine& engine, mech3::Mech3App& app) {
      auto* os = dynamic_cast<mech3::OptionsState*>(app.current());
      auto* c = os ? dynamic_cast<mech3::ControlsScreen*>(engine.screen_of(os->screen_)) : nullptr;
      if (stage == 0 && at_main_menu(app)) {
        const_cast<mech3::MainMenu*>(mech3::main_menu())->buttons[mech3::MainMenuButton::kOptions].on_left_up();
        stage = 1;
      } else if (stage == 1 && os) {
        auto* g = dynamic_cast<mech3::GameOptionsScreen*>(engine.screen_of(os->screen_));
        if (!g) return false;
        g->controls.on_left_up();
        stage = 2;
      } else if (stage == 2 && c) {
        c->select_command(0);  // Forward throttle: the throttle's axis
        c->assign_axis.on_left_up();
        stage = 3;
      } else if (stage == 3) {
        auto* st = dynamic_cast<mech3::AxisPopupState*>(app.current());
        if (!st || !st->popup) return ++wait > 60;
        mech3::AxisCycle& src = st->popup->sources;
        for (int32_t i = 0; i < 16; ++i) {
          src.select(i);
          if (src.selected_value() == 7) {
            listed = true;
            break;
          }
        }
        if (listed) st->popup->ok.on_left_up();
        bound = mech3::axis_table().axes[0];
        stage = 4;
      } else if (stage == 4) {
        if (!listed) return true;
        bound = mech3::axis_table().axes[0];
        return ++wait > 5;
      }
      return false;
    });
    std::printf("  popup (bugs %d): slider 0 listed %d; the throttle %d x %g + %g\n", bugs, listed, bound.source,
                bound.scale, bound.offset);
    EXPECT(stage == 4);
    EXPECT(listed == bugs);
    if (bugs) {
      // Invert shown checked for the defaults' negative scale: -0.5 / 32767.5
      // and 0.5 + 0.5, the slider's low end full ahead.
      EXPECT(bound.source == 7 && std::fabs(bound.scale * 32767.5f + 0.5f) < 1e-4f && std::fabs(bound.offset - 1.0f) < 1e-4f);
    }
  }
}


// W59 (Owen's v1.0 crash, zmth::load+0x1d late in c4b): 0x004ed530 takes a
// node's world position on a matrix of its own (push, identity, 0x004ed280,
// pop). The port's shortcut ran 0x004ed280 on whatever the stack's top was
// for a changed node: outside a draw that is the empty base slot (a write
// through null in v1.0). Between frames, a moved centroid read as the exe.
TEST(node_world_cached_of_a_moved_node_keeps_the_matrix_stack_headless) {
  if (!have_game()) return;
  bool checked = false, same = false;
  zmth::StackFaults faults;
  cheat_mission("w59_cached_write", 0, 1, 400, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 5) return false;
    auto* centroid = static_cast<zcls::Node*>(mech3::mech_centroid_of(mech3::mission_player_mech()));
    EXPECT(centroid != nullptr && centroid->cls() == 5);
    if (!centroid) return true;
    float want[3];
    zcls::node_world_position(centroid, want);
    auto* d = static_cast<uint8_t*>(centroid->data);
    d[0] |= 0x20;  // its cached world matrix out of date, as after a move
    EXPECT(zmth::matrix_stack().top == 0);
    zmth::stack_faults() = {};
    float got[3] = {9, 9, 9};
    mech3::node_world_cached(centroid, got);
    faults = zmth::stack_faults();
    same = std::fabs(got[0] - want[0]) < 1e-3f && std::fabs(got[1] - want[1]) < 1e-3f &&
           std::fabs(got[2] - want[2]) < 1e-3f;
    checked = true;
    return true;
  });
  EXPECT(checked && same);
  EXPECT(faults.empty == 0 && faults.under_pop == 0 && faults.over_push == 0);
  EXPECT(zmth::matrix_stack().top == 0);
}

// W58 (docs/lancemate-pathing.md, Testing): the lance's long way. The player
// stands where the grid finds the longest way round from the lancemate (the
// straight line blocked, 150..400 m off), the lancemate following as he does unordered; the exe (bugs off), the port before (W17,
// W27) and the grid, in range and in sight of him by when, and stuck how long.
namespace {
struct FarRun {
  bool placed = false, ordered = false;
  int crossings = 0, reached = -1, stuck_s = 0, paths = 0, frames = 0;
  float d0 = 0, d_min = 1e9f, d_end = 0, range = 0;
};
FarRun lance_far_run(int32_t index, int32_t number, bool bugs, bool nav) {
  namespace nv = mech3::ai::nav;
  FarRun out;
  const NavAllies nav_on(nav);
  const bool bugs_was = zfix::all();
  zfix::set_all(bugs);
  g_cheat_mission_op = index >= 3 ? 4 : index + 1;  // c1 c2 c3, c4 and c4b
  void *mate = nullptr, *player = nullptr;
  mech3::ai::Brain* brain = nullptr;
  float mark[2] = {};
  auto pos_of = [](void* m, float o[3]) {
    mech3::LaunchedMech x;
    mech3::describe_mech(m, &x);
    o[0] = x.pos[0], o[1] = x.pos[1], o[2] = x.pos[2];
  };
  cheat_mission("w58_far_write", index, number, 6000, [&](int f, mech3::GameEngine& engine, CheatKeys&) {
    out.frames = f;
    if (f == 3) {
      int32_t made = 0;
      const mech3::AiMechMade* ai = mech3::mission_ai_mechs(&made);
      player = mech3::mech_mission_player();
      const zgame::Handle pv = player ? engine.handle_of(player) : 0;
      for (int32_t i = 0; i < made && !mate; ++i) {  // the lance's first (Dominic where he is)
        const mech3::ai::AiTarget* t = ai[i].mech ? mech3::ai::brain_hooks().targetable(engine.handle_of(ai[i].mech)) : nullptr;
        if (t && pv && t->is_ally(pv)) {
          if (!ai[i].name || std::string(ai[i].name) != "Dominic_Paine") continue;
          mate = ai[i].mech;
          brain = static_cast<mech3::AiControls*>(ai[i].controls)->brain.get();
        }
      }
      if (!mate) return true;
      float d[3];
      pos_of(mate, d);
      // By the grid: the place 150..400 m off whose straight line is blocked
      // and whose way round is the longest against it. With bug fixes off the
      // mission start left the last mission's grid (only this test asks for it then).
      if (!bugs) nv::restart();
      nv::service(0.0f, 0);
      nv::Grid& g = nv::grid();
      const int ct = nv::tile_of(nv::cell_of(d[0])), rt = nv::tile_of(nv::cell_of(d[2]));
      for (int tz = rt - 3; tz <= rt + 3; ++tz)
        for (int tx = ct - 3; tx <= ct + 3; ++tx) {
          int budget = 1 << 30;
          g.build(tx, tz, &budget);
        }
      g.parked_t = -1e30f;
      nv::service(0.0f, 0);  // the parked vehicles, on the built tiles
      float best[3] = {}, best_ratio = 0;
      for (float r = 150.0f; r <= 400.0f; r += 50.0f)
        for (int k = 0; k < 24; ++k) {
          const float a = static_cast<float>(k) * 0.2617994f;
          const float x = d[0] + std::sin(a) * r, z = d[2] + std::cos(a) * r;
          const int lv = g.level_at(nv::cell_of(x), nv::cell_of(z), d[1]);
          if (lv < 0 || !g.walkable(nv::cell_of(x), nv::cell_of(z), lv)) continue;
          const float p[3] = {x, g.cell(nv::cell_of(x), nv::cell_of(z), lv)->y, z};
          if (nv::line_clear(g, d, p)) continue;
          float clamped[3];
          if (mech3::ai::brain_hooks().inout_clamp(engine.handle_of(mate), p, clamped)) continue;
          nv::Way way;
          if (nv::find_path(g, d, p, &way) != nv::Find::kOk) continue;
          float len = 0, px = d[0], pz = d[2];
          for (const auto& q : way) len += std::hypot(q[0] - px, q[2] - pz), px = q[0], pz = q[2];
          if (len / r > best_ratio) best_ratio = len / r, best[0] = x, best[1] = p[1], best[2] = z;
        }
      out.crossings = static_cast<int>(best_ratio * 100.0f);
      if (best_ratio < 1.1f) return true;
      mech3::program_mech_set_invincible(player, true);
      mech3::program_mech_set_invincible(mate, true);
      mech3::move_mech(player, best, 0.0f);
      out.range = brain->params.get<float>(0x28);
      out.placed = true;
      return false;
    }
    if (!out.placed || f < 5) return false;
    if (f == 5) out.ordered = true;  // a lancemate follows unordered (form on me is his "stop")
    float a[3], b[3];
    pos_of(mate, a), pos_of(player, b);
    const float dd = std::hypot(a[0] - b[0], a[2] - b[2]);
    if (f == 5) out.d0 = dd, mark[0] = a[0], mark[1] = a[2];
    out.d_min = std::min(out.d_min, dd), out.d_end = dd;
    if (f % 120 == 0) {  // not 2 m in 2 s, past his range
      if (dd > out.range && std::hypot(a[0] - mark[0], a[2] - mark[1]) < 2.0f) out.stuck_s += 2;
      mark[0] = a[0], mark[1] = a[2];
      if (std::getenv("W58_LOG")) std::fprintf(stderr, "  t %d: at %.0f %.0f %.0f, %.0f m, player %.0f %.0f %.0f\n", f / 60, a[0], a[1], a[2], dd, b[0], b[1], b[2]);
    }
    if (auto* fs = dynamic_cast<mech3::ai::FollowState*>(brain->current().state.get()))
      out.paths = std::max(out.paths, static_cast<int>(fs->nav.follow.paths));
    if (dd <= out.range && std::fabs(a[1] - b[1]) < 12.0f) {
      const float e[3] = {a[0], a[1] + 6, a[2]}, t[3] = {b[0], b[1] + 5, b[2]};
      if (!wall_between_seg(e, t)) return out.reached = f, true;
    }
    return f >= 5400;  // 90 s
  });
  g_cheat_mission_op = 0;
  zfix::set_all(bugs_was);
  return out;
}
}  // namespace

TEST(mission_lance_far_way_before_and_after_headless) {
  if (!have_game()) return;
  const std::array<int32_t, 2> kMissions[] = {{0, 4}, {1, 1}, {1, 3}, {2, 2}, {2, 5}, {4, 4}, {4, 6}};
  int measured = 0;
  const char* one = std::getenv("W58_ONE");  // "2 5": that mission, the grid only
  for (const auto& m : kMissions) {
    if (one && std::atoi(one) != m[0] * 10 + m[1]) continue;
    const FarRun exe = one ? FarRun{} : lance_far_run(m[0], m[1], false, false), port = one ? FarRun{} : lance_far_run(m[0], m[1], true, false),
                   grid = lance_far_run(m[0], m[1], true, true);
    if (!grid.placed) {
      std::printf("  %sm%d: no Dominic, or no place with a long way round\n", mech3::mission_dir(m[0]), m[1]);
      continue;
    }
    ++measured;
    for (const auto& [r, who] : {std::pair{&exe, "the exe"}, {&port, "W17/W27"}, {&grid, "the grid"}})
      std::printf("  %sm%d %s: %.0f m, the way %d%% of it, ordered %d, range %.0f; there at %d (%.1f s) of %d, nearest %.0f m, stuck %d s, paths %d\n",
                  mech3::mission_dir(m[0]), m[1], who, r->d0, r->crossings, r->ordered, r->range, r->reached,
                  r->reached / 60.0f, r->frames, r->d_min, r->stuck_s, r->paths);
  }
  EXPECT(measured >= 3);
}

// W58: Epona's first mission (Owen: "that one gave me the most trouble with
// lancemate pathing"). c2m4 has two floors, the ground and the works 90 m
// under it, joined by ramps and thin walkways. The player stands in the works,
// Dominic follows from the start: the exe, the port before, the grid.
namespace {
struct WorksRun {
  bool placed = false, door = false;
  int reached = -1, stuck_s = 0, paths = 0, way_points = 0, way_at = 0, frames = 0;
  float way_len = 0, d0 = 0, d_min = 1e9f, y_end = 0, range = 0;
};
WorksRun c2m4_works_run(bool bugs, bool nav, const float spot[3], const float* mate_at = nullptr) {
  namespace nv = mech3::ai::nav;
  WorksRun out;
  const NavAllies nav_on(nav);
  const bool bugs_was = zfix::all();
  zfix::set_all(bugs);
  g_cheat_mission_op = 2;
  void *mate = nullptr, *player = nullptr;
  mech3::ai::Brain* brain = nullptr;
  float mark[2] = {};
  auto pos_of = [](void* m, float o[3]) {
    mech3::LaunchedMech x;
    mech3::describe_mech(m, &x);
    o[0] = x.pos[0], o[1] = x.pos[1], o[2] = x.pos[2];
  };
  cheat_mission("w58_works_write", 1, 4, 14000, [&](int f, mech3::GameEngine& engine, CheatKeys&) {
    out.frames = f;
    (void)engine;
    if (f == 3) {
      int32_t made = 0;
      const mech3::AiMechMade* ai = mech3::mission_ai_mechs(&made);
      player = mech3::mech_mission_player();
      for (int32_t i = 0; i < made && !mate; ++i)
        if (ai[i].mech && ai[i].name && std::string(ai[i].name) == "Dominic_Paine") {
          mate = ai[i].mech;
          brain = static_cast<mech3::AiControls*>(ai[i].controls)->brain.get();
        }
      if (!mate || !player) return true;
      mech3::program_mech_set_invincible(player, true);
      mech3::program_mech_set_invincible(mate, true);
      // On the floor there nearest the height asked.
      const auto on_floor = [](const float* in, float* o) {
        namespace nv = mech3::ai::nav;
        nv::Floor fl[nv::kLevels];
        const int n = nv::zcls_world().ground(in[0], in[2], fl, nv::kLevels);
        o[0] = in[0], o[1] = in[1], o[2] = in[2];
        float best = 1e30f;
        for (int i = 0; i < n; ++i)
          if (std::fabs(fl[i].y - in[1]) < best) best = std::fabs(fl[i].y - in[1]), o[1] = fl[i].y;
      };
      float there[3];
      if (mate_at) on_floor(mate_at, there), mech3::move_mech(mate, there, 0.0f);
      on_floor(spot, there), mech3::move_mech(player, there, 0.0f);
          out.range = brain->params.get<float>(0x28);
      out.placed = true;
      return false;
    }
    if (!out.placed || f < 5) return false;
    float a[3], b[3];
    pos_of(mate, a), pos_of(player, b);
    const float dd = std::hypot(a[0] - b[0], a[2] - b[2]);
    if (f == 5) out.d0 = dd, mark[0] = a[0], mark[1] = a[2];
    out.d_min = std::min(out.d_min, dd), out.y_end = a[1];
    if (f % 120 == 0) {
      if (dd > out.range && std::hypot(a[0] - mark[0], a[2] - mark[1]) < 2.0f) out.stuck_s += 2;
      mark[0] = a[0], mark[1] = a[2];
      if (std::getenv("W58_LOG")) {
        std::fprintf(stderr, "  t %d: at %.0f %.0f %.0f, %.0f m\n", f / 60, a[0], a[1], a[2], dd);
      }
    }
    if (f == 60)  // the player has shot the factory door down (its target's destroy_anim)
      if (zeff::AnimDef* door = zeff::anim_find("open_fdoors")) zeff::anim_start(door, nullptr, 0, 0, 0), out.door = true;
    if (auto* fs = dynamic_cast<mech3::ai::FollowState*>(brain->current().state.get())) {
      out.paths = std::max(out.paths, static_cast<int>(fs->nav.follow.paths));
      if (!fs->nav.follow.path.empty() && out.way_points == 0) {
        out.way_points = static_cast<int>(fs->nav.follow.path.size());
        out.way_at = f;
        float px = a[0], pz = a[2];
        for (const auto& q : fs->nav.follow.path) {
          out.way_len += std::hypot(q[0] - px, q[2] - pz), px = q[0], pz = q[2];
          if (std::getenv("W58_LOG")) std::fprintf(stderr, "    way %.0f %.0f %.0f\n", q[0], q[1], q[2]);
        }
      }
    }
    if (dd <= out.range && std::fabs(a[1] - b[1]) < 12.0f) return out.reached = f, true;
    return f >= 10800;  // 3 minutes
  });
  g_cheat_mission_op = 0;
  zfix::set_all(bugs_was);
  return out;
}
}  // namespace

TEST(mission_c2m4_lancemate_reaches_the_works_headless) {
  if (!have_game()) return;
  // The hub past the thin conveyor, on its floor (the land 40 m over it).
  const float spot[3] = {-1024.0f, std::getenv("W58_Y") ? static_cast<float>(std::atof(std::getenv("W58_Y"))) : -98.8f, -1500.0f};
  const bool only = std::getenv("W58_ONLY") != nullptr;
  const WorksRun exe = only ? WorksRun{} : c2m4_works_run(false, false, spot), port = only ? WorksRun{} : c2m4_works_run(true, false, spot),
                 grid = c2m4_works_run(true, true, spot);
  for (const auto& [r, who] : {std::pair{&exe, "the exe"}, {&port, "W17/W27"}, {&grid, "the grid"}})
    std::printf("  %s: door %d, %.0f m off, there at %d (%.0f s) of %d frames, nearest %.0f m, his height at the end %.0f, stuck %d s, paths %d (the first at %d: %d points, %.0f m)\n", who, r->door, r->d0,
                r->reached, r->reached / 60.0f, r->frames, r->d_min, r->y_end, r->stuck_s, r->paths, r->way_at, r->way_points, r->way_len);
  EXPECT(exe.placed && exe.reached < 0);  // the exe's: his feet read the land over the tunnel as a wall
  EXPECT(port.reached > 0 && port.stuck_s < 10);
  EXPECT(grid.placed && grid.reached > 0 && grid.stuck_s < 10);
}

// W58, Owen's two: "you're on a conveyor" and "a river you keep bumping into".
// The player on the works' slab line (c2m4's conveyor); then Dominic on one bank
// of the river and the player on the other, 125 m up from its bridge.
TEST(mission_c2m4_lancemate_to_the_conveyor_and_over_the_river_headless) {
  if (!have_game()) return;
  const char* only = std::getenv("W58_CASE");
  const auto three = [&](const char* what, const float* spot, const float* from) {
    const WorksRun exe = c2m4_works_run(false, false, spot, from), port = c2m4_works_run(true, false, spot, from), grid = c2m4_works_run(true, true, spot, from);
    for (const auto& [r, who] : {std::pair{&exe, "the exe"}, {&port, "W17/W27"}, {&grid, "the grid"}})
      std::printf("  %s, %s: %.0f m off, there at %d (%.0f s), nearest %.0f m, height at the end %.0f, stuck %d s, paths %d\n", what, who, r->d0, r->reached,
                  r->reached / 60.0f, r->d_min, r->y_end, r->stuck_s, r->paths);
    EXPECT(grid.placed && grid.reached > 0);
    EXPECT(grid.stuck_s <= port.stuck_s + 4 || (port.reached > 0 && grid.reached < port.reached));  // or there sooner all the same
  };
  if (!only || only[0] == 'c') {
    // The strip's top joins nothing until its pieces move in play: he comes
    // under it, in range; his reaching the top is for the playtest.
    const float under[3] = {-1100.0f, -102.3f, -1380.0f};
    three("under the conveyor", under, nullptr);
  }
  if (!only || only[0] == 'r') {
    const float east[3] = {-2050.0f, 0.0f, -180.0f}, west[3] = {-2260.0f, 0.0f, -180.0f};
    three("river", east, west);
  }
}

// W61: reset_process_state leaves zEntity's update walk as a new process has
// it (no resume point into a freed list).
TEST(reset_process_state_clears_the_entity_walk) {
  static int stale[4];
  zent::budget().resume = &stale[2];
  zent::budget().left = 7;
  reset_process_state();
  EXPECT(zent::budget().resume == nullptr && zent::budget().left == 0 && zent::budget().per_frame == 0x40);
  std::vector<int> list = {0, 1, 2, 3};
  std::vector<int> order;
  zent::budget().update_all(list, [&](int i) { order.push_back(i); });
  EXPECT(order == (std::vector<int>{0, 1, 2, 3}));  // from the start
}

// The AI net editor's way in (S5 sitting 3a): in c1m1, the editor entered as
// Shift+F12's command does, EDIT AI NETS's dialog lists the mission's nets,
// net_01 opened from it, GOTO Net puts the stealth at its first node, and
// Save Changes (no edits yet) writes readerm1.zbd to the write dir's
// "editor edits" mod, the same bytes as the install's, turned on in mw3.cfg,
// and says so in the panel's last row.
TEST(mission_c1m1_net_editor_saves_into_its_own_mod_headless) {
  if (!have_game()) return;
  bool listed = false, opened = false, placed = false, saved = false, same = false, on = false;
  std::string status, write_dir;
  float node[3] = {}, at[3] = {};
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("net_editor_write", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    write_dir = zutl::mounts().write;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::edit_ai_nets(0);
    mech3::NetDialog& d = mech3::net_dialog();
    for (size_t i = 0; i < d.items.size(); ++i)
      if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i), listed = true;
    mech3::net_dialog_close();
    mech3::NetEditor* e = mech3::net_editor();
    opened = e && e->net && e->net->header.net == 1 && mech3::editor_state().mode == 1;
    if (!opened) return true;
    if (mech3::ai::NetNode* n = e->net->node(0)) node[0] = n->pos()[0], node[1] = n->pos()[1], node[2] = n->pos()[2];
    mech3::net_editor_goto(0);
    mech3::VehicleSummary v;
    if (mech3::describe_vehicle(mech3::program_stealth(), &v)) {
      at[0] = v.pos[0], at[1] = v.pos[1], at[2] = v.pos[2];
      placed = std::hypot(at[0] - node[0], at[2] - node[2]) < 0.5f;
    }
    mech3::net_editor_save(0);
    status = mech3::editor_panel().rows[24]->text;
    mech3::net_editor_exit(0);
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  const std::filesystem::path out = std::filesystem::path(write_dir) / "mods" / "editor edits" / "zbd" / "c1" / "readerm1.zbd";
  const auto bytes = [](const std::filesystem::path& p) {
    std::ifstream in(p, std::ios::binary);
    return std::string((std::istreambuf_iterator<char>(in)), std::istreambuf_iterator<char>());
  };
  saved = std::filesystem::exists(out);
  same = saved && bytes(out) == bytes(std::filesystem::path(MW3_GAME_DIR) / "zbd" / "c1" / "readerm1.zbd");
  for (const std::string& m : mech3::entry_mods_on(write_dir)) on = on || m == "editor edits";
  std::printf("  listed %d, opened %d, the stealth at %.1f %.1f %.1f for node_00 %.1f %.1f %.1f (%d); saved %d, the same "
              "bytes %d, on %d; the panel: \"%s\"\n", listed, opened, at[0], at[1], at[2], node[0], node[1], node[2], placed,
              saved, same, on, status.c_str());
  EXPECT(listed && opened && placed);
  EXPECT(saved && same && on);
  EXPECT(status.find("editor edits") != std::string::npos && status.find("play it from MODS") != std::string::npos);
  EXPECT(std::filesystem::exists(out.parent_path().parent_path().parent_path() / "mw3-editor.txt"));
}

// The net editor's frame on the mission (S5 sitting 3b): net_01 opened, its
// view holds a mark for each node and its links; the stealth's reticle pick
// (0x004a58d0) gives the frame a point in the world; Move Node puts node_00
// there once the mouse has left it and come back (the marks' flags as the
// window would set them); a left-up on two picks links the second (a node
// with no link to node_00) to the first and makes the editor anew on the
// same net, one link more in its view; Save Changes then writes both into
// the editor's mod (the record cache, S5 sitting 4: read back from the saved
// archive through the reader, node_02 as the install has it); leaving puts
// the camera's far clip back.
TEST(mission_c1m1_net_editor_view_move_and_link_headless) {
  if (!have_game()) return;
  int32_t marks = -1, nodes = -1, links = -1, moved = 0, linked = 0, rebuilt = 0, ground = 0;
  float pick[3] = {}, node[3] = {}, far_before = 0, far_after = 0, kept = 0, dist = 0;
  int32_t step = 0, at = 0, other = -1, cached = -1;
  std::string write_dir, status;
  float node2[3] = {};
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("net_editor_view", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    mech3::NetEditor* e = mech3::net_editor();
    float near_z = 0;
    if (step == 0) {
      mech3::editor_hooks().camera_clip(&near_z, &far_before);
      mech3::editor_key(mech3::kEditorCommand);
      mech3::edit_ai_nets(0);
      mech3::NetDialog& d = mech3::net_dialog();
      for (size_t i = 0; i < d.items.size(); ++i)
        if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
      mech3::net_dialog_close();
      e = mech3::net_editor();
      if (!e || !e->view) return true;
      kept = e->far_clip;
      nodes = e->net->count(), marks = int32_t(e->view->marks.size()), links = int32_t(e->view->links.size());
      for (int32_t k = 1; k < nodes && other < 0; ++k)  // a node with no link to node_00 yet
        if (e->net->node(k)->link_index(e->net->node(0)) < 0) other = k;
      if (other < 0) return true;
      e->view->pick(&e->view->marks[0]);
      mech3::net_editor_move(0);
      step = 1, at = f;
      return false;
    }
    if (!e) return true;
    if (step == 1 && f > at + 2) {  // the frames ran: the mouse was off it
      ground = e->has_ground;
      if (e->move == 2) e->view->marks[0].flags = 1, step = 2, at = f;
    } else if (step == 2 && f > at + 2) {
      for (int i = 0; i < 3; ++i) pick[i] = e->ground[i], node[i] = e->net->node(0)->pos()[i];
      if (const float* c = mech3::editor_hooks().camera_pos())  // a crossing: nearer than the far plane
        dist = std::sqrt((c[0] - pick[0]) * (c[0] - pick[0]) + (c[1] - pick[1]) * (c[1] - pick[1]) + (c[2] - pick[2]) * (c[2] - pick[2]));
      moved = e->move == 3 && e->dirty && std::hypot(node[0] - pick[0], node[2] - pick[2]) < 0.01f;
      e->view->marks[0].flags |= 2;  // clicked: done
      e->view->pick(&e->view->marks[size_t(other)]);
      e->view->on_left_up();
      step = 3, at = f;
    } else if (step == 3 && f > at + 1) {
      mech3::ai::NetNode* n = e->net->node(other);
      linked = n && n->link_index(e->net->node(0)) >= 0;
      rebuilt = e->net && e->dirty && e->view->picks.empty() && int32_t(e->view->links.size()) == links + 1;
      cached = int32_t(e->net->ref->file->cache.size());
      for (int i = 0; i < 3; ++i) node2[i] = e->net->node(2)->pos()[i];
      write_dir = zutl::mounts().write;
      mech3::net_editor_save(0);
      status = mech3::editor_panel().rows[24]->text;
      mech3::net_editor_exit(0);
      mech3::editor_key(mech3::kEditorCommand);
      mech3::editor_hooks().camera_clip(&near_z, &far_after);
      return true;
    }
    return f > at + 200;
  });
  mech3::app_key_calls().debug_camera = false;
  std::printf("  net_01: %d nodes, %d marks, %d links; the pick %d at %.1f %.1f %.1f (%.0f from the camera), node_00 now %.1f %.1f %.1f (%d); "
              "node_%02d linked %d, made anew %d; far clip %.0f, kept %.0f, after %.0f\n", nodes, marks, links, ground, pick[0], pick[1],
              pick[2], dist, node[0], node[1], node[2], moved, other, linked, rebuilt, far_before, kept, far_after);
  EXPECT(nodes > 1 && marks == nodes && links > 0);
  EXPECT(ground && (pick[0] != 0 || pick[2] != 0) && dist > 0 && dist < far_before * 0.99f);
  EXPECT(moved && linked && rebuilt);
  EXPECT(kept == far_before && far_after == far_before);
  // The save, read back through the reader.
  bool saved_move = false, saved_link = false, saved_same = false;
  const std::filesystem::path out = std::filesystem::path(write_dir) / "mods" / "editor edits" / "zbd" / "c1" / "readerm1.zbd";
  if (std::filesystem::exists(out) && other > 0) {
    const zutl::Mounts keep = zutl::mounts();
    zrdr::close_archives(true);
    zrdr::init();
    if (zrdr::open_archive(out.string().c_str(), true)) {
      mech3::ai::NetFile f(1, "net_01.zrd");
      if (f.load() != 0) {
        char key[16];
        std::snprintf(key, sizeof key, "node_%02d", other);
        if (const mech3::ai::NetNodeRec* r = f.node_named("node_00"))
          saved_move = r->pos[0] == node[0] && r->pos[1] == node[1] && r->pos[2] == node[2];
        if (const mech3::ai::NetNodeRec* r = f.node_named(key))
          saved_link = std::find(r->links.begin(), r->links.end(), 0) != r->links.end();
        if (const mech3::ai::NetNodeRec* r = f.node_named("node_02"))
          saved_same = r->pos[0] == node2[0] && r->pos[1] == node2[1] && r->pos[2] == node2[2];
        f.unload();
      }
    }
    zrdr::close_archives(true);
    zutl::mounts() = keep;
  }
  std::printf("  the cache %d records; saved: node_00 moved %d, node_%02d's link %d, node_02 as it was %d; \"%s\"\n", cached,
              saved_move, other, saved_link, saved_same, status.c_str());
  EXPECT(cached == 2 && saved_move && saved_link && saved_same);
}

// New Net (0x00402c90, S5 sitting 4b) on c1m1: a net of the first free number
// with its first node at the stealth's pick, its mark picked; a second node
// linked from the frame's hand-over (a new node at the pick, 0x004bd1f0);
// Save Changes adds net_NN.zrd to the editor mod's copy of the mission's
// archive; the next start, on the same write folder, builds it with both
// nodes where they were put.
TEST(mission_c1m1_new_net_saved_and_loaded_next_start_headless) {
  if (!have_game()) return;
  int32_t id = -1, nodes = 0, step = 0, at = 0, found = 0, read = 0;
  float first[3] = {}, again[3] = {}, pick[3] = {};
  std::string write_dir, status;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("new_net", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    mech3::NetEditor* e = mech3::net_editor();
    if (step == 0) {
      write_dir = zutl::mounts().write;
      mech3::editor_key(mech3::kEditorCommand);  // the view on the stealth: its reticle picks from its next frame
      step = -1, at = f;
      return false;
    }
    if (step == -1) {
      if (f < at + 3) return false;
      mech3::edit_ai_nets(0);
      mech3::net_dialog().selected = 0;  // New Net
      mech3::net_dialog_close();
      e = mech3::net_editor();
      if (!e || !e->net) return true;
      id = e->net->header.net;
      for (int i = 0; i < 3; ++i) first[i] = e->net->node(0)->pos()[i];
      mech3::editor_hooks().ground_pick(pick);  // the same frame's
      step = 1, at = f;
      return false;
    }
    if (!e) return true;
    if (step == 1 && f > at + 2) {
      // The picks emptied, the hand-over made by hand: a new node at the pick,
      // linked to... none; it links the handed-over node_00 to it.
      e->view->to_link.push_back(&e->view->marks[0]);
      e->view->picks.clear();
      step = 2, at = f;
    } else if (step == 2 && f > at + 1) {
      nodes = e->net->count();
      mech3::net_editor_save(0);
      status = mech3::editor_panel().rows[24]->text;
      mech3::net_editor_exit(0);
      mech3::editor_key(mech3::kEditorCommand);
      return true;
    }
    return f > at + 200;
  });
  // The next start on the same folder (the editor mod ticked for the game's own campaign entry).
  const char* keep = g_cheat_mission_dir;
  g_cheat_mission_dir = write_dir.c_str();
  const std::vector<std::string> on = mech3::entry_mods_on(write_dir);
  g_cheat_mission_mods = &on;
  cheat_mission("new_net_again", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    found = znet::find(id) != nullptr;
    mech3::ai::NetRef ref(id, nullptr);
    if (ref.file) {
      read = ref.count();
      if (const mech3::ai::NetNodeRec* r = ref.file->node_named("node_00"))
        for (int i = 0; i < 3; ++i) again[i] = r->pos[i];
    }
    return true;
  });
  g_cheat_mission_dir = keep;
  g_cheat_mission_mods = nullptr;
  mech3::app_key_calls().debug_camera = false;
  std::printf("  new net_%02d: %d nodes, node_00 at %.1f %.1f %.1f; \"%s\"; next start: built %d, %d nodes read, node_00 "
              "at %.1f %.1f %.1f\n", id, nodes, first[0], first[1], first[2], status.c_str(), found, read, again[0],
              again[1], again[2]);
  EXPECT(id > 0 && id < 100 && nodes == 2 && status.find("editor edits") != std::string::npos);
  EXPECT(first[0] == pick[0] && first[1] == pick[1] && first[2] == pick[2] && (pick[0] != 0 || pick[2] != 0));
  EXPECT(found && read == 2 && again[0] == first[0] && again[1] == first[1] && again[2] == first[2]);
}

// The vehicle editor's save (ours, S7f; docs/editor.md, The vehicle
// editor's save) on c1m1: owens_01's pilot name, skin and place on p2 and a
// range on p1, Apply, Save (twice: the second keeps the first as .bak); the
// next start, on the same write folder, gives its brain the saved values.
TEST(mission_c1m1_vehicle_editor_saved_and_read_next_start_headless) {
  if (!have_game()) return;
  std::string write_dir, saved, picked;
  float x0 = 0, range = 0, x_again = 0, range_again = 0;
  int32_t skin_again = -1;
  std::string pilot_again;
  bool bak = false, found_again = false;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("vehicle_save", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    write_dir = zutl::mounts().write;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::edit_vehicles(0);
    mech3::VehicleEditor* e = mech3::vehicle_editor();
    if (!e) return true;
    for (size_t i = 0; i < e->items.size(); ++i)
      if (e->items[i].name == "owens_01") {
        *e->form.fields[0].i = static_cast<int32_t>(i);
        e->form.changed(e->form.fields[0]);
        picked = e->items[i].name;
      }
    if (picked.empty()) return true;
    mech3::vehicle_editor_tab(mech3::kPageP2);
    mech3::Dialog& p2 = e->pages[mech3::kPageP2];
    x0 = e->params.get<float>(0x08) + 10.0f;
    p2.at(1200).text = std::to_string(x0);
    p2.at(1243).text = "Saved Pilot";
    p2.at(1284).text = "9";
    mech3::vehicle_editor_tab(mech3::kPageP1);
    range = 123.5f;
    e->pages[mech3::kPageP1].at(1210).text = "123.5";  // Leave Net Range to Target (+0x20, squared in play)
    e->form.press("Save");  // Apply, then the save
    e->form.press("Save");  // again: the first kept as .bak
    saved = e->saved;
    e->form.press("OK");
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  const std::filesystem::path out = std::filesystem::path(write_dir) / "mods" / "editor edits" / "zbd" / "c1" / "readerm1.zbd";
  bak = std::filesystem::exists(out.string() + ".bak");
  // The next start on the same folder (the editor mod ticked for the game's own campaign entry).
  const char* keep = g_cheat_mission_dir;
  g_cheat_mission_dir = write_dir.c_str();
  const std::vector<std::string> on = mech3::entry_mods_on(write_dir);
  const int32_t refs_between = mech3::ai::aiv_file().refs;  // nothing holds aiv.zrd: the next start reads it anew
  g_cheat_mission_mods = &on;
  cheat_mission("vehicle_save_again", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::edit_vehicles(0);
    if (mech3::VehicleEditor* e = mech3::vehicle_editor()) {
      for (const mech3::VehicleEditorItem& it : e->items)
        if (it.name == picked)
          if (mech3::ai::AiParams* b = mech3::vehicle_editor_hooks().brain_params(it.vehicle)) {
            found_again = true;
            x_again = b->get<float>(0x08);
            range_again = std::sqrt(b->get<float>(0x20));
            skin_again = b->skin();
            pilot_again = b->pilot ? b->pilot : "";
          }
      e->form.press("OK");
    }
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  g_cheat_mission_dir = keep;
  g_cheat_mission_mods = nullptr;
  mech3::app_key_calls().debug_camera = false;
  std::printf("  %s: \"%s\"; .bak %d; next start: found %d, x %.2f (wanted %.2f), range %.2f, skin %d, pilot \"%s\"\n",
              picked.c_str(), saved.c_str(), bak, found_again, x_again, x0, range_again, skin_again,
              pilot_again.c_str());
  EXPECT(picked == "owens_01" && saved.find("editor edits") != std::string::npos && bak && refs_between == 0);
  EXPECT(found_again && std::fabs(x_again - x0) < 0.01f && std::fabs(range_again - range) < 0.001f && skin_again == 9 &&
         pilot_again == "Saved Pilot");
}

// The editor's help (ours, docs/editor-guide.md) on c1m1: every form the
// editor opens (the net dialog, Node Params, Add vehicle, Delete's question,
// the net window and its Open list, the Tree View, the Help window, Mech AI
// and its message, New Weapon) and both menus: each field, button, tab and row has a tip,
// and each tip names an item its form has.
namespace {
struct HelpSeen {
  std::map<std::string, std::set<std::string>> items;  // by the help table's form
  std::vector<std::string> missing;
  std::string table_of(const std::string& title) {
    for (const mech3::HelpForm& f : mech3::help_forms())
      if (title == f.form) return f.form;
    std::string key = title.substr(0, std::min(title.find("##"), title.find(':')));
    return key;
  }
  void item(const std::string& title, const std::string& it) {
    items[table_of(title)].insert(it);
    if (!mech3::help_tip(title, it)) missing.push_back(title + " / " + it);
  }
  void form(const mech3::EditorForm& f) {
    for (const mech3::FormField& x : f.fields) {
      if (x.kind == mech3::FormField::kLabel) continue;
      if (x.kind == mech3::FormField::kTabs)
        for (const std::string& c : x.choices) item(f.title, "tab " + c);
      else
        item(f.title, x.label);
    }
    for (const mech3::FormButton& b : f.buttons) item(f.title, b.label);
  }
  void menu(const char* table, const mech3::EditorMenu& m) {
    for (int32_t r = 0; r < m.count; ++r) {
      std::string t = m.rows[r].text;
      while (!t.empty() && t.front() == ' ') t.erase(t.begin());
      if (!t.empty()) item(table, t);
    }
  }
};
}  // namespace

// Teleport (docs/editor.md, Teleport) on c1m1, the editor up: the TELEPORT row's form lists Current Location, the
// mission's nav points and c1's shipped places; Mission 2 Start picked and OK: the player there, the places
// (nav points too) saved into the mission's mod as zbd\c1\location.zrd, which the next open reads.
TEST(mission_c1m1_teleport_moves_the_player_headless) {
  if (!have_game()) return;
  std::string listed, saved;
  float at[3] = {}, want[3] = {-1408.7f, -10.0f, -845.3f};
  bool moved = false, read_again = false, cancel_stayed = false;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("teleport", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::ai::net_save_into_mod() = "tp";
    mech3::teleport_open(0);
    mech3::EditorForm& form = mech3::teleport_form();
    mech3::FormField* place = form.field("place");
    if (!place || !place->combo) return true;
    for (const std::string& t : place->combo->texts()) listed += t + "; ";
    for (size_t i = 0; i < place->combo->items.size(); ++i)
      if (place->combo->items[i].text == "Mission 2 Start") *place->i = static_cast<int32_t>(i);
    form.changed(*place);
    form.press("OK");
    saved = mech3::teleport_last_saved();
    moved = mech3::mech_world_position(mech3::mech_mission_player(), at);
    mech3::teleport_open(0);  // again: the saved file is read now
    if (mech3::FormField* again = mech3::teleport_form().field("place"); again && again->combo)
      for (const std::string& t : again->combo->texts()) read_again = read_again || t == "Mission 2 Start";
    // Cancel after a pick: no move, no save (FIX (bug); the exe moved and saved).
    mech3::EditorForm& form2 = mech3::teleport_form();
    if (mech3::FormField* again = form2.field("place"); again && again->combo)
      for (size_t i = 0; i < again->combo->items.size(); ++i)
        if (again->combo->items[i].text == "IA_base") *again->i = static_cast<int32_t>(i), form2.changed(*again);
    std::error_code ec;
    const auto written = std::filesystem::last_write_time(saved, ec);
    std::filesystem::last_write_time(saved, written - std::chrono::hours(1), ec);  // a save would move it on
    form2.press("Cancel");
    float after[3] = {};
    cancel_stayed = mech3::mech_world_position(mech3::mech_mission_player(), after) &&
                    std::fabs(after[0] - at[0]) < 0.01f && std::fabs(after[2] - at[2]) < 0.01f &&
                    std::filesystem::last_write_time(saved, ec) == written - std::chrono::hours(1) &&
                    !mech3::form_shown(&form2);
    mech3::ai::net_save_into_mod().clear();
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  std::printf("  listed: %s\n  at %.1f %.1f %.1f; saved %s\n", listed.c_str(), at[0], at[1], at[2], saved.c_str());
  EXPECT(listed.find("Current Location") != std::string::npos && listed.find("IA_base") != std::string::npos &&
         listed.find("Mission 2 Start") != std::string::npos);
  EXPECT(moved && std::fabs(at[0] - want[0]) < 0.5f && std::fabs(at[2] - want[2]) < 0.5f);
  EXPECT(!saved.empty() && saved.find("tp") != std::string::npos && saved.find("c1") != std::string::npos && read_again);
  EXPECT(cancel_stayed);
}

TEST(mission_c1m1_editor_help_covers_every_form_headless) {
  if (!have_game()) return;
  HelpSeen seen;
  int32_t forms = 0, previews = 0;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("editor_help", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    const auto look = [&](const mech3::EditorForm& form) {
      if (!mech3::form_shown(&form)) return;
      ++forms;
      seen.form(form);
    };
    mech3::editor_key(mech3::kEditorCommand);
    seen.menu("main menu", mech3::editor_main_menu_rows());
    seen.menu("net menu", mech3::editor_net_menu_rows());
    mech3::edit_ai_nets(0);
    look(mech3::net_dialog_form());
    mech3::NetDialog& d = mech3::net_dialog();
    for (size_t i = 0; i < d.items.size(); ++i)
      if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
    mech3::net_dialog_close();
    mech3::NetEditor* e = mech3::net_editor();
    if (!e) return true;
    e->view->pick(&e->view->marks[0]);
    mech3::node_params_open(0);
    look(mech3::node_params_form());
    mech3::node_params_form().press("Cancel");
    mech3::add_vehicle_open(0);
    look(mech3::add_vehicle_form());
    mech3::add_vehicle_form().press("Cancel");
    mech3::net_editor_delete(0);
    look(mech3::net_delete_form());
    mech3::net_delete_form().press("Cancel");
    mech3::net_params_open(0);
    look(mech3::net_window_form());
    mech3::net_window_form().press("Open");
    look(mech3::net_open_form());
    mech3::net_open_form().press("Cancel");
    mech3::net_window_form().press("OK");
    mech3::tree_view(0);
    look(mech3::tree_form());
    mech3::tree_form().press("OK");
    mech3::help_open(0);
    look(mech3::help_window());
    mech3::help_window().press("Close");
    mech3::net_editor_exit(0);
    mech3::edit_vehicles(0);
    if (mech3::VehicleEditor* v = mech3::vehicle_editor()) {
      look(v->form);
      v->pages[mech3::kPageP1].at(1209).text = "not a number";
      v->form.press("Apply");
      look(v->message);
      v->message.press("OK");
      v->form.press("OK");
    }
    // New Weapon (EDIT WEAPONS) opens only from MODS's EDITOR: a session stands in for one.
    mech3::ModsEditSession& ms = mech3::mods_edit_session();
    const mech3::ModsEditSession kept = ms;
    ms.active = true, ms.mod = "help_check";
    mech3::new_weapon_open(0);
    look(mech3::new_weapon_form());
    // A muzzle and a sound picked: shown in the running mission by the engine's own calls (no preview hooks).
    for (const char* slot : {"muzzle", "firing sound"})
      if (mech3::FormField* x = mech3::new_weapon_form().field(slot); x && x->choices.size() > 2) {
        *x->i = 2;
        mech3::new_weapon_form().changed(*x);
        ++previews;
      }
    mech3::new_weapon_form().press("Cancel");
    ms = kept;
    mech3::teleport_open(0);
    look(mech3::teleport_form());
    mech3::teleport_form().press("Cancel");
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  // Each table's tips against what its form showed.
  std::vector<std::string> stale;
  for (const mech3::HelpForm& f : mech3::help_forms()) {
    const auto it = seen.items.find(f.form);
    for (const mech3::HelpTip& t : f.tips)
      if (it == seen.items.end() || !it->second.count(t.item)) stale.push_back(std::string(f.form) + " / " + t.item);
  }
  std::printf("  %d forms looked at, %zu tables; no tip: %zu; tips for nothing: %zu\n", forms, seen.items.size(),
              seen.missing.size(), stale.size());
  for (const std::string& m : seen.missing) std::printf("    no tip: %s\n", m.c_str());
  for (const std::string& m : stale) std::printf("    tip for nothing: %s\n", m.c_str());
  EXPECT(forms == 12 && previews == 2 && seen.missing.empty() && stale.empty());
}

// The Ai Network Editor window (181, S5 sitting 4c) on c1m1: Change Net
// Params opens it; Open lists the open archives' net files, net_01.zrd among
// them; the second listed opened shows its net in its own editor beside the
// edited one, stepped each frame (0x00404290); OK closes it.
TEST(mission_c1m1_net_window_shows_a_second_net_headless) {
  if (!have_game()) return;
  int32_t step = 0, at = 0, listed = 0, nodes = -1, marks = -1, frames_run = 0;
  bool has01 = false, closed = false;
  std::string opened;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("net_window", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    if (step == 0) {
      mech3::editor_key(mech3::kEditorCommand);
      mech3::edit_ai_nets(0);
      mech3::NetDialog& d = mech3::net_dialog();
      for (size_t i = 0; i < d.items.size(); ++i)
        if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
      mech3::net_dialog_close();
      if (!mech3::net_editor()) return true;
      mech3::net_params_open(0);
      // Open's list, as its button does; the second file opened.
      mech3::net_window_form().press("Open");
      mech3::EditorForm& open = mech3::net_open_form();
      const std::vector<std::string>& files = open.fields[0].choices;
      listed = static_cast<int32_t>(files.size());
      for (const std::string& t : files) has01 = has01 || t == "net_01.zrd";
      opened = files.size() > 1 ? files[1] : std::string();
      *open.fields[0].i = 1;
      open.press("Open");
      mech3::NetWindow* w = mech3::net_window();
      if (!w || !w->hosted) return true;
      nodes = w->hosted->net->count();
      step = 1, at = f;
      return false;
    }
    mech3::NetWindow* w = mech3::net_window();
    if (step == 1 && f > at + 3) {
      marks = w && w->hosted ? int32_t(w->hosted->view->marks.size()) : -1;
      frames_run = w && w->hosted && w->hosted->camera ? 1 : 0;  // its frame ran: it read the camera
      mech3::net_window_form().press("OK");
      closed = !mech3::net_window();
      mech3::net_editor_exit(0);
      mech3::editor_key(mech3::kEditorCommand);
      return true;
    }
    return f > at + 200;
  });
  mech3::app_key_calls().debug_camera = false;
  std::printf("  Open listed %d net files on its first page (net_01.zrd %d); opened \"%s\": %d nodes, %d marks, stepped %d; closed %d\n", listed,
              has01, opened.c_str(), nodes, marks, frames_run, closed);
  EXPECT(listed > 2 && has01 && nodes > 0 && marks == nodes && frames_run && closed);
}

// Node Params (ours, S5 sitting 4c) on c1m1: net_01's node_00 picked, its
// speed set to 0.25 and its gate named in its form, OK, Save Changes; read back from
// the editor mod's archive through the reader, both there.
TEST(mission_c1m1_node_params_saved_headless) {
  if (!have_game()) return;
  std::string write_dir, status;
  bool formed = false;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("node_params", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    write_dir = zutl::mounts().write;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::edit_ai_nets(0);
    mech3::NetDialog& d = mech3::net_dialog();
    for (size_t i = 0; i < d.items.size(); ++i)
      if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
    mech3::net_dialog_close();
    mech3::NetEditor* e = mech3::net_editor();
    if (!e) return true;
    e->view->pick(&e->view->marks[0]);
    mech3::node_params_open(0);
    formed = mech3::node_params_open_now();
    mech3::EditorForm& form = mech3::node_params_form();
    *form.field("speed")->on = 1, *form.field("speed")->f = 0.25f;
    *form.field("gate")->text = "gate_x";
    form.press("OK");
    mech3::net_editor_save(0);
    status = mech3::editor_panel().rows[24]->text;
    mech3::net_editor_exit(0);
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  bool speed = false, gate = false;
  const std::filesystem::path out = std::filesystem::path(write_dir) / "mods" / "editor edits" / "zbd" / "c1" / "readerm1.zbd";
  if (std::filesystem::exists(out)) {
    const zutl::Mounts keep = zutl::mounts();
    zrdr::close_archives(true);
    zrdr::init();
    if (zrdr::open_archive(out.string().c_str(), true)) {
      mech3::ai::NetFile f(1, "net_01.zrd");
      if (f.load() != 0) {
        if (const mech3::ai::NetNodeRec* r = f.node_named("node_00")) {
          speed = r->speed_on == 1 && r->speed == 0.25f;
          gate = r->gate && std::string(r->gate) == "gate_x";
        }
        f.unload();
      }
    }
    zrdr::close_archives(true);
    zutl::mounts() = keep;
  }
  std::printf("  the form %d; \"%s\"; saved: speed %d, gate %d\n", formed, status.c_str(), speed, gate);
  EXPECT(formed && speed && gate);
}

// Add veh to node (ours, S5 sitting 4c) on c1m1: net_01's node_00 picked, a
// ttruck chosen as a foe, OK: a ttruck_03 is made at the node on net 1 now,
// and its record saved into the editor mod's aiv.zrd with ttruck_01's tags,
// read back through our aiv reader (net, place, yaw, team, the tags' params).
TEST(mission_c1m1_add_vehicle_made_and_saved_headless) {
  if (!have_game()) return;
  std::string write_dir, status, name;
  size_t before = 0, after = 0;
  bool found = false, place_ok = false;
  float node[3] = {};
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("add_vehicle", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    write_dir = zutl::mounts().write;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::edit_ai_nets(0);
    mech3::NetDialog& d = mech3::net_dialog();
    for (size_t i = 0; i < d.items.size(); ++i)
      if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
    mech3::net_dialog_close();
    mech3::NetEditor* e = mech3::net_editor();
    if (!e) return true;
    for (int i = 0; i < 3; ++i) node[i] = e->net->node(0)->pos()[i];
    e->view->pick(&e->view->marks[0]);
    before = mech3::program_vehicles().size();
    mech3::add_vehicle_open(0);
    const std::vector<std::string> types = mech3::add_vehicle_types();
    const int32_t t = int32_t(std::find(types.begin(), types.end(), "ttruck") - types.begin());
    mech3::EditorForm& form = mech3::add_vehicle_form();
    *form.field("vehicle type")->i = t;
    *form.field("side")->i = 1, form.changed(*form.field("side"));  // Friend -> Foe
    form.press("OK");
    status = mech3::editor_panel().rows[24]->text;
    name = mech3::add_vehicle_last();
    after = mech3::program_vehicles().size();
    for (void* v : mech3::program_vehicles()) {
      mech3::VehicleSummary sm;
      if (mech3::describe_vehicle(v, &sm) && sm.name && name == sm.name) {
        found = true;
        place_ok = std::hypot(sm.pos[0] - node[0], sm.pos[2] - node[2]) < 1.0f;
      }
    }
    mech3::net_editor_exit(0);
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  // The saved record through the aiv reader.
  bool read_back = false, tags = false;
  float rpos[3] = {};
  int32_t rnet = -1, rteam = -1;
  const std::filesystem::path out = std::filesystem::path(write_dir) / "mods" / "editor edits" / "zbd" / "c1" / "readerm1.zbd";
  if (std::filesystem::exists(out)) {
    const zutl::Mounts keep = zutl::mounts();
    zrdr::close_archives(true);
    zrdr::init();
    mech3::ai::aiv_file_reset();
    if (zrdr::open_archive(out.string().c_str(), true)) {
      mech3::ai::AivRecord rec, ref;
      if (mech3::ai::AivRecord* r = rec.read_named(name.c_str())) {
        read_back = true;
        rnet = r->kind(), rteam = r->team();
        for (int i = 0; i < 3; ++i) rpos[i] = r->get<float>(0x08 + 4 * i);
        if (mech3::ai::AivRecord* t1 = ref.read_named("ttruck_01"))
          tags = std::memcmp(r->raw + 0x1c, t1->raw + 0x1c, 0xb0) == 0;  // params .. skin as ttruck_01's
      }
    }
    mech3::ai::aiv_file_reset();
    zrdr::close_archives(true);
    zutl::mounts() = keep;
  }
  std::printf("  \"%s\"; vehicles %zu -> %zu, %s made %d at the node %d; read back %d: net %d, team %d, at %.1f %.1f %.1f "
              "(node %.1f %.1f %.1f), ttruck_01's tags %d\n", status.c_str(), before, after, name.c_str(), found, place_ok,
              read_back, rnet, rteam, rpos[0], rpos[1], rpos[2], node[0], node[1], node[2], tags);
  EXPECT(name == "ttruck_03" && after == before + 1 && found && place_ok);
  EXPECT(status.find("ttruck_03 on net 1: made") == 0 && status.find("editor edits") != std::string::npos);
  EXPECT(read_back && rnet == 1 && rteam == 2 && rpos[0] == node[0] && rpos[2] == node[2] && tags);
}

// The Tree View (0x00402bf0 -> 0x004b5580, S5 sitting 4) on c1m1: the
// world's item first, closed; opened, its children and then an "area R C"
// item for each partition cell (0x004b56b0); a cell opened shows its nodes;
// the list pages; OK closes it and gives the net menu back.
TEST(mission_c1m1_tree_view_shows_the_world_headless) {
  if (!have_game()) return;
  std::string world_row, area_row, after_area;
  size_t kids = 0, areas = 0, cells = 0;
  bool closed = false, shown = false, opened_area = false;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("tree_view", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 10) return false;
    mech3::editor_key(mech3::kEditorCommand);
    mech3::edit_ai_nets(0);
    mech3::NetDialog& d = mech3::net_dialog();
    for (size_t i = 0; i < d.items.size(); ++i)
      if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
    mech3::net_dialog_close();
    if (!mech3::net_editor()) return true;
    mech3::tree_view(0);
    mech3::TreeWindow* t = mech3::tree_window();
    if (!t) return true;
    for (const mech3::TreeItem& k : t->root.kids) (k.data ? kids : areas)++;
    shown = mech3::form_shown(&mech3::tree_form());
    std::vector<std::string> rows = mech3::tree_rows();
    world_row = rows.empty() ? "" : rows[0];
    mech3::tree_press(0);  // the world opened
    rows = mech3::tree_rows();
    for (size_t i = 0; i < rows.size() && area_row.empty(); ++i)
      for (const mech3::TreeItem& k : t->root.kids)
        if (!k.data && !k.kids.empty() && rows[i] == "  + " + k.text) {
          area_row = rows[i];
          cells = k.kids.size();
          mech3::tree_press(int32_t(i));
          after_area = mech3::tree_rows()[i];
          opened_area = after_area == "  - " + k.text && mech3::tree_rows().size() == rows.size() + cells;
          break;
        }
    mech3::tree_form().press("OK");
    closed = !mech3::tree_window() && !mech3::form_shown(&mech3::tree_form());
    mech3::net_editor_exit(0);
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  std::printf("  \"%s\": %zu children, %zu areas; shown %d; \"%s\" -> \"%s\" (%zu nodes); closed %d\n", world_row.c_str(),
              kids, areas, shown, area_row.c_str(), after_area.c_str(), cells, closed);
  EXPECT(world_row.find("+ ") == 0 && kids > 0 && areas > 0 && shown);
  EXPECT(opened_area && cells > 0 && closed);
}

// The reload (ours, S5 sitting 4): net_01 edited and saved on c1m1 is built
// again from the edit, and every AI mech and vehicle whose orders were on the
// old net is on the new one (net_hooks().rebuilt, on 0x004bed90's pattern);
// the mission runs on.
TEST(mission_c1m1_saved_net_hands_its_vehicles_over_headless) {
  if (!have_game()) return;
  std::vector<mech3::ai::Brain*> on_old;
  mech3::ai::AiNet* old_net = nullptr;
  mech3::ai::AiNet* new_net = nullptr;
  int32_t step = 0, at = 0, moved_over = 0, still_old = 0, ran = 0;
  std::string status;
  const auto brains = [] {
    std::vector<mech3::ai::Brain*> v;
    for (void* b : mech3::program_ai_brains()) v.push_back(static_cast<mech3::ai::Brain*>(b));
    return v;
  };
  const auto on = [](mech3::ai::Brain* b, mech3::ai::AiNet* n) {
    for (const mech3::ai::Order& o : b->orders)
      if (o.net && o.net->net() == n) return true;
    return false;
  };
  // The address can come back from the allocator; the hook's two calls show the net was remade.
  static int32_t drops, builds;
  static void (*wired)(mech3::ai::AiNet*, mech3::ai::AiNet*);
  drops = builds = 0;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("net_handover", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    if (step == 0) {
      mech3::editor_key(mech3::kEditorCommand);
      mech3::edit_ai_nets(0);
      mech3::NetDialog& d = mech3::net_dialog();
      for (size_t i = 0; i < d.items.size(); ++i)
        if (d.items[i].first == "net_01") d.selected = static_cast<int32_t>(i);
      mech3::net_dialog_close();
      mech3::NetEditor* e = mech3::net_editor();
      if (!e) return true;
      old_net = e->net->net;
      wired = mech3::ai::net_hooks().rebuilt;
      mech3::ai::net_hooks().rebuilt = [](mech3::ai::AiNet* o, mech3::ai::AiNet* n) {
        (n ? builds : drops)++;
        wired(o, n);
      };
      for (mech3::ai::Brain* b : brains())
        if (on(b, old_net)) on_old.push_back(b);
      float p[3] = {e->net->node(1)->pos()[0] + 8.0f, e->net->node(1)->pos()[1], e->net->node(1)->pos()[2]};
      if (e->net->node(1)->set_pos(p)) e->net->node(1)->relink();
      mech3::net_editor_save(0);
      status = mech3::editor_panel().rows[24]->text;
      new_net = e->net->net;
      mech3::ai::net_hooks().rebuilt = wired;
      for (mech3::ai::Brain* b : on_old) (on(b, new_net) ? moved_over : still_old)++;
      mech3::net_editor_exit(0);
      mech3::editor_key(mech3::kEditorCommand);
      step = 1, at = f;
      return false;
    }
    ++ran;
    return f > at + 90;
  });
  mech3::app_key_calls().debug_camera = false;
  std::printf("  net dropped %d, built %d; \"%s\"; %zu brains on net_01 before, %d on the new net after, %d not; ran %d frames on\n", drops, builds, status.c_str(),
              on_old.size(), moved_over, still_old, ran);
  EXPECT(status.find("running now") != std::string::npos && new_net && old_net && drops == 1 && builds == 1);
  EXPECT(!on_old.empty() && moved_over == int32_t(on_old.size()) && ran > 80);
}

// The vehicle editor's shell on c1m1 (S7c): EDIT VEHICLES lists zEntity's
// mechs and AI vehicles ("player" among them); an AI one picked, its pilot's
// name changed and Applied: the brain has it and aiv.zrd's cache keeps the
// record; the mission runs on; OK closes it.
TEST(mission_c1m1_vehicle_editor_applies_to_a_brain_headless) {
  if (!have_game()) return;
  std::vector<std::string> names;
  std::string picked, brain_pilot, cached_pilot;
  int32_t ran = 0, at = -1;
  bool closed = false;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("vehicle_editor", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    if (at < 0) {
      mech3::editor_key(mech3::kEditorCommand);
      mech3::edit_vehicles(0);
      mech3::VehicleEditor* e = mech3::vehicle_editor();
      if (!e) return true;
      for (const mech3::VehicleEditorItem& it : e->items) names.push_back(it.name);
      for (size_t i = 0; i < e->items.size() && picked.empty(); ++i)
        if (mech3::vehicle_editor_hooks().brain_params(e->items[i].vehicle)) {
          *e->form.fields[0].i = static_cast<int32_t>(i);
          e->form.changed(e->form.fields[0]);
          picked = e->items[i].name;
        }
      if (picked.empty()) return true;
      std::free(e->params.pilot);
      e->params.pilot = strdup("Tester");
      e->form.press("Apply");
      if (mech3::ai::AiParams* b = mech3::vehicle_editor_hooks().brain_params(e->items[size_t(e->selected)].vehicle))
        brain_pilot = b->pilot ? b->pilot : "";
      if (const mech3::ai::AivRecord* r = mech3::ai::aiv_file().cached(picked.c_str())) cached_pilot = r->pilot ? r->pilot : "";
      at = f;
      return false;
    }
    ++ran;
    if (f < at + 60) return false;
    if (mech3::VehicleEditor* e = mech3::vehicle_editor()) e->form.press("OK");
    closed = !mech3::vehicle_editor();
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  std::string list;
  for (const std::string& n : names) list += n + " ";
  std::printf("  %zu listed: %s; picked %s: brain's pilot \"%s\", cached \"%s\"; ran %d frames; closed %d\n", names.size(),
              list.c_str(), picked.c_str(), brain_pilot.c_str(), cached_pilot.c_str(), ran, closed);
  EXPECT(std::find(names.begin(), names.end(), "player") != names.end() && names.size() > 1);
  EXPECT(!picked.empty() && brain_pilot == "Tester" && cached_pilot == "Tester" && ran >= 60 && closed);
}

// The vehicle editor's p2 in play (S7d, docs/editor.md, The vehicle
// editor's pages): a made vehicle's page shows its home net; Show checked
// and Apply puts a second net editor on that net (0x004044c0, on the frame's
// list); a place typed, Apply and Send home put the vehicle there
// (0x004bc960); Show InOut draws the boundary's walls under the world
// (0x004c4730); both unchecked take them down again.
TEST(mission_c1m1_vehicle_editor_p2_shows_the_net_and_sends_home_headless) {
  if (!have_game()) return;
  std::string picked, net_name;
  bool shown = false, freed = false, on_net = false;
  int32_t walls_parents = 0, walls_models = 0, walls_polys = 0;
  float target[3] = {}, before[3] = {}, after[3] = {};
  int32_t at = -1, home = -1;
  mech3::app_key_calls().debug_camera = true;
  cheat_mission("vehicle_editor_p2", 0, 1, 2000, [&](int f, mech3::GameEngine&, CheatKeys&) {
    if (f < 30) return false;
    mech3::VehicleEditor* e = mech3::vehicle_editor();
    if (at < 0) {
      mech3::editor_key(mech3::kEditorCommand);
      mech3::edit_vehicles(0);
      e = mech3::vehicle_editor();
      if (!e) return true;
      mech3::VehicleSummary sm;
      for (size_t i = 0; i < e->items.size() && picked.empty(); ++i)
        if (mech3::describe_vehicle(e->items[i].vehicle, &sm) && sm.ai_controls &&
            mech3::vehicle_editor_hooks().brain_params(e->items[i].vehicle)) {
          *e->form.fields[0].i = static_cast<int32_t>(i);
          e->form.changed(e->form.fields[0]);
          picked = e->items[i].name;
          for (int k = 0; k < 3; ++k) before[k] = sm.pos[k];
        }
      if (picked.empty()) return true;
      mech3::vehicle_editor_tab(mech3::kPageP2);
      mech3::Dialog& p2 = e->pages[mech3::kPageP2];
      home = e->params.get<int32_t>(0x04);
      const mech3::DlgCombo& nets = p2.at(1238).combo;
      if (nets.cur >= 0) net_name = nets.items[size_t(nets.cur)].text;
      p2.at(1249).check = 1;  // Show
      p2.at(1282).check = 1;  // Show InOut
      target[0] = before[0] + 20.0f, target[1] = before[1], target[2] = before[2] + 20.0f;
      p2.at(1200).text = std::to_string(target[0]);
      p2.at(1202).text = std::to_string(target[2]);
      e->form.press("Apply");
      shown = e->shown && e->shown->net && e->shown->net->net && e->shown->net->net->get_id() == home;
      if (zcls::Node* w = mech3::ai::inout_view()) {
        walls_parents = w->parent_count(), walls_models = w->child_count();
        for (int32_t k = 0; k < w->child_count(); ++k)
          if (const zmod::Model* m = w->children[k]->model) walls_polys += static_cast<int32_t>(m->count(0x10));
      }
      e->form.changed(*e->form.field("Send home"));
      at = f;
      return false;
    }
    if (f < at + 30) return false;
    mech3::VehicleSummary sm;
    if (e && mech3::describe_vehicle(e->items[size_t(e->selected)].vehicle, &sm))
      for (int k = 0; k < 3; ++k) after[k] = sm.pos[k];
    if (e) {
      if (mech3::ai::AiParams* b = mech3::vehicle_editor_hooks().brain_params(e->items[size_t(e->selected)].vehicle))
        on_net = b->get<int32_t>(0x04) == home;
      e->pages[mech3::kPageP2].at(1249).check = 0;
      e->pages[mech3::kPageP2].at(1282).check = 0;
      e->form.press("Apply");
      freed = !e->shown && mech3::ai::inout_view_empty();
      e->form.press("OK");
    }
    mech3::editor_key(mech3::kEditorCommand);
    return true;
  });
  mech3::app_key_calls().debug_camera = false;
  std::printf("  picked %s, home net %d (%s); Show's editor %d; sent from %.1f,%.1f to %.1f,%.1f (wanted %.1f,%.1f); "
              "on its net %d; freed %d\n",
              picked.c_str(), home, net_name.c_str(), shown, before[0], before[2], after[0], after[2], target[0],
              target[2], on_net, freed);
  std::printf("  the boundary's walls: %d models, %d triangles, %d parent\n", walls_models, walls_polys, walls_parents);
  EXPECT(!picked.empty() && !net_name.empty() && shown && freed && on_net);
  EXPECT(walls_parents == 1 && walls_models > 0 && walls_polys > 0);
  EXPECT(std::fabs(after[0] - target[0]) < 2.0f && std::fabs(after[2] - target[2]) < 2.0f);
}
